    public void setTool(int newTool) {
        tool = newTool;
        drawing = false;
        draggingSelection = false;
        __CadCanvasView_dragUndoSaved = false;
        activeHandle = -1;
        snapVisible = false;
        freePoints.clear();
        invalidate();
    }

    public int getTool() { return tool; }
