    public String toggleMultiSelectMode() {
        multiSelectMode = !multiSelectMode;
        anchorMoveState = 0;
        invalidate();
        return multiSelectMode
                ? "textSelection On: Roy text text until text/text text; Roy text text text until text Selection text"
                : "textSelection Off: Selection text";
    }

    public boolean isMultiSelectMode() {
        return multiSelectMode;
    }

    public String beginAnchorMove() {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.isEmpty()) return "First text text text text text Selection text";
        anchorMoveState = 1;
        anchorSource = null;
        __SmartCadCanvasView_notifyStatus("text Snap: Point text text Roy text selected text");
        invalidate();
        return "Point text text Roy text selected text";
    }

    public String groupSelected() {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() < 2) return "text text text text text Selection text";
        __SmartCadCanvasView_pruneGroups();
        for (List<Object> g : groups) {
            if (__SmartCadCanvasView_sameIdentitySet(g, selectedObjects)) return "text text text text text text text";
        }
        groups.add(new ArrayList<>(selectedObjects));
        invalidate();
        return selectedObjects.size() + " text text became";
    }

    public String ungroupSelected() {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.isEmpty()) return "First text text text text text Selection text";
        int removed = 0;
        Iterator<List<Object>> it = groups.iterator();
        while (it.hasNext()) {
            List<Object> g = it.next();
            if (__SmartCadCanvasView_intersectsIdentity(g, selectedObjects)) {
                it.remove();
                removed++;
            }
        }
        invalidate();
        return removed == 0 ? "text text text Selection was not found" : "text text text";
    }

    public void clearSmartSelection() {
        selectedObjects.clear();
        __SmartCadCanvasView_setBaseSelected(null);
        anchorMoveState = 0;
        invalidate();
    }


    public void setTool(int newTool) {
        super.setTool(newTool);
        selectionBoxCandidate = false;
        selectionBoxActive = false;
        pendingTapHit = null;
        groupDragging = false;
        chipPressed = false;
        if (newTool != TOOL_SELECT) anchorMoveState = 0;
    }


    public String selectedInfo() {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() > 1) {
            return selectedObjects.size() + " text selected";
        }
        return super.selectedInfo();
    }


    public void clearAll() {
        super.clearAll();
        selectedObjects.clear();
        groups.clear();
        anchorMoveState = 0;
    }


    public void undo() {
        super.undo();
        selectedObjects.clear();
        groups.clear();
        anchorMoveState = 0;
    }


    public void deleteSelected() {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) {
            super.deleteSelected();
            selectedObjects.clear();
            __SmartCadCanvasView_pruneGroups();
            return;
        }
        coreSaveUndo();
        List<Object> all = __SmartCadCanvasView_entities();
        all.removeAll(selectedObjects);
        selectedObjects.clear();
        __SmartCadCanvasView_setBaseSelected(null);
        __SmartCadCanvasView_pruneGroups();
        invalidate();
    }


    public void moveSelected(float dx, float dy) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) {
            super.moveSelected(dx, dy);
            __SmartCadCanvasView_syncFromBaseIfNeeded();
            return;
        }
        coreSaveUndo();
        for (Object e : selectedObjects) __SmartCadCanvasView_translate(e, dx, dy);
        invalidate();
    }


    public void copySelected(float dx, float dy) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) {
            super.copySelected(dx, dy);
            __SmartCadCanvasView_syncFromBaseIfNeeded();
            return;
        }
        coreSaveUndo();
        List<Object> copies = new ArrayList<>();
        for (Object e : selectedObjects) {
            Object c = __SmartCadCanvasView_entityCopy(e);
            if (c != null) {
                __SmartCadCanvasView_translate(c, dx, dy);
                __SmartCadCanvasView_entities().add(c);
                copies.add(c);
            }
        }
        __SmartCadCanvasView_setSelection(copies);
        invalidate();
    }


    public String offsetSelected(float distance) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.offsetSelected(distance);
        coreSaveUndo();
        List<Object> copies = new ArrayList<>();
        for (Object e : selectedObjects) {
            Object c = __SmartCadCanvasView_entityOffsetCopy(e, distance);
            if (c != null) {
                __SmartCadCanvasView_entities().add(c);
                copies.add(c);
            }
        }
        if (copies.isEmpty()) return "Offset text text selected text text text";
        __SmartCadCanvasView_setSelection(copies);
        invalidate();
        return "Offset Roy " + copies.size() + " text Apply text";
    }


    public String rotateSelected(float deg) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.rotateSelected(deg);
        PointF c = __SmartCadCanvasView_selectionCenter();
        coreSaveUndo();
        for (Object e : selectedObjects) __SmartCadCanvasView_entityRotate(e, c.x, c.y, deg);
        invalidate();
        return "text " + __SmartCadCanvasView_format(deg) + "° Roy " + selectedObjects.size() + " text";
    }


    public String scaleSelected(float factor) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.scaleSelected(factor);
        if (factor <= 0f) return "Scale text text text text text";
        PointF c = __SmartCadCanvasView_selectionCenter();
        coreSaveUndo();
        for (Object e : selectedObjects) __SmartCadCanvasView_entityScale(e, c.x, c.y, factor);
        invalidate();
        return "Scale × " + __SmartCadCanvasView_format(factor) + " Roy Selection";
    }


    public String mirrorSelected(boolean acrossXAxis, float axisValue) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.mirrorSelected(acrossXAxis, axisValue);
        coreSaveUndo();
        for (Object e : selectedObjects) {
            if (acrossXAxis) __SmartCadCanvasView_entityMirrorHorizontal(e, axisValue);
            else __SmartCadCanvasView_entityMirrorVertical(e, axisValue);
        }
        invalidate();
        return acrossXAxis ? "text text text text Axis X" : "text text text text Axis Y";
    }


    public String arraySelected(int count, float dx, float dy) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.arraySelected(count, dx, dy);
        if (count < 2 || count > 200) return "text Array text text 2 text 200 text";
        coreSaveUndo();
        List<Object> seed = new ArrayList<>(selectedObjects);
        List<Object> lastCopies = new ArrayList<>();
        for (int i = 1; i < count; i++) {
            lastCopies.clear();
            for (Object e : seed) {
                Object c = __SmartCadCanvasView_entityCopy(e);
                if (c != null) {
                    __SmartCadCanvasView_translate(c, dx * i, dy * i);
                    __SmartCadCanvasView_entities().add(c);
                    lastCopies.add(c);
                }
            }
        }
        if (!lastCopies.isEmpty()) __SmartCadCanvasView_setSelection(new ArrayList<>(lastCopies));
        invalidate();
        return "Array text: " + count + " text";
    }


    public String applySelectedDimension(String raw) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() > 1) return "text Exact Dimension text text text text Selection text";
        return super.applySelectedDimension(raw);
    }


    public String assignSelectedLayer(String name) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.assignSelectedLayer(name);
        if (name == null || name.trim().isEmpty()) return "text text is empty";
        coreSaveUndo();
        for (Object e : selectedObjects) __SmartCadCanvasView_entitySetLayer(e, name.trim());
        invalidate();
        return selectedObjects.size() + " text text text " + name.trim() + " text text";
    }


    public String setMaterial(String material) {
        __SmartCadCanvasView_syncFromBaseIfNeeded();
        if (selectedObjects.size() <= 1) return super.setMaterial(material);
        int color = __SmartCadCanvasView_materialColorLocal(material);
        coreSaveUndo();
        for (Object e : selectedObjects) __SmartCadCanvasView_entitySetColor(e, color);
        invalidate();
        return "Material Roy " + selectedObjects.size() + " text Apply text";
    }


    public String setLayerVisible(String name, boolean visible) {
        String result = super.setLayerVisible(name, visible);
        __SmartCadCanvasView_pruneSelection();
        return result;
    }


    public String executeCommand(String raw) {
        if (raw == null) return "";
        String normalized = __SmartCadCanvasView_normalizeDigits(raw).trim().replace(',', ' ');
        if (normalized.isEmpty()) return "";
        String[] a = normalized.split("\\s+");
        String cmd = a[0].toUpperCase(Locale.US);
        try {
            switch (cmd) {
                case "M": case "MOVE":
                    if (a.length < 3) return "text text dx text dy text text";
                    moveSelected(Float.parseFloat(a[1]), Float.parseFloat(a[2]));
                    return "text text";
                case "CO": case "COPY":
                    if (a.length < 3) return "text text dx text dy text text";
                    copySelected(Float.parseFloat(a[1]), Float.parseFloat(a[2]));
                    return "text text";
                case "O": case "OFFSET":
                    if (a.length < 2) return "Distance Offset text text text";
                    return offsetSelected(Float.parseFloat(a[1]));
                case "RO": case "ROTATE":
                    if (a.length < 2) return "Angle text text text";
                    return rotateSelected(Float.parseFloat(a[1]));
                case "SC": case "SCALE":
                    if (a.length < 2) return "text Scale text text text";
                    return scaleSelected(Float.parseFloat(a[1]));
                case "MI": case "MIRROR":
                    if (a.length < 2) return "MIRROR X text MIRROR Y";
                    float axis = a.length > 2 ? Float.parseFloat(a[2]) : 0f;
                    if ("X".equalsIgnoreCase(a[1])) return mirrorSelected(true, axis);
                    if ("Y".equalsIgnoreCase(a[1])) return mirrorSelected(false, axis);
                    return "MIRROR X text MIRROR Y";
                case "AR": case "ARRAY":
                    if (a.length < 4) return "count dx dy text text text";
                    return arraySelected(Integer.parseInt(a[1]), Float.parseFloat(a[2]), Float.parseFloat(a[3]));
                case "ERASE": case "DELETE":
                    deleteSelected();
                    return "Delete text";
                case "ASSIGNLAYER":
                    if (a.length < 2) return "text text text text text";
                    return assignSelectedLayer(a[1]);
                case "MATERIAL":
                    if (a.length < 2) return "text Material text text text";
                    return setMaterial(a[1]);
                case "GROUP":
                    return groupSelected();
                case "UNGROUP":
                    return ungroupSelected();
                default:
                    int beforeEntityCount = __SmartCadCanvasView_entities().size();
                    String result = super.executeCommand(normalized);
                    Object commandSelected = __SmartCadCanvasView_baseSelected();
                    if (__SmartCadCanvasView_entities().size() > beforeEntityCount && commandSelected != null) {
                        // A creation command makes its new entity the authoritative
                        // single selection.  Do not let stale multi-selection state
                        // clear CadCanvasView.selected immediately after creation.
                        selectedObjects.clear();
                        selectedObjects.add(commandSelected);
                        __SmartCadCanvasView_syncBaseSelectionWithSmart();
                    } else {
                        __SmartCadCanvasView_syncFromBaseIfNeeded();
                    }
                    return result;
            }
        } catch (Exception e) {
            return "Number format is invalid";
        }
    }


    protected void onDraw(Canvas canvas) {
        super.onDraw(canvas);

        __SmartCadCanvasView_pruneSelection();
        if (selectedObjects.size() > 1) {
            for (Object e : selectedObjects) {
                RectF r = __SmartCadCanvasView_entityBounds(e);
                if (r == null) continue;
                RectF s = __SmartCadCanvasView_worldRectToScreen(r);
                float pad = 8f;
                s.inset(-pad, -pad);
                canvas.drawRoundRect(s, 10f, 10f, multiSelectionPaint);
            }
        }

        if (selectionBoxActive) {
            RectF r = __SmartCadCanvasView_normalizedScreenRect(boxStartX, boxStartY, boxEndX, boxEndY);
            canvas.drawRect(r, selectionBoxFill);
            canvas.drawRect(r, selectionBoxPaint);
        }

        dimensionChip.setEmpty();
        if (selectedObjects.size() == 1 && getTool() == TOOL_SELECT && anchorMoveState == 0) {
            Object e = selectedObjects.get(0);
            PointF c = __SmartCadCanvasView_entityCenter(e);
            if (c != null) {
                PointF s = __SmartCadCanvasView_worldToScreen(c.x, c.y);
                float w = 170f;
                float h = 48f;
                float left = __SmartCadCanvasView_clamp(s.x - w / 2f, 8f, Math.max(8f, getWidth() - w - 8f));
                float top = __SmartCadCanvasView_clamp(s.y - 82f, 8f, Math.max(8f, getHeight() - h - 42f));
                dimensionChip.set(left, top, left + w, top + h);
                canvas.drawRoundRect(dimensionChip, 20f, 20f, chipPaint);
                canvas.drawText("✎ Exact Dimension", dimensionChip.centerX(),
                        dimensionChip.centerY() + 10f, chipTextPaint);
            }
        }

        if (anchorMoveState > 0) {
            chipTextPaint.setTextSize(25f);
            chipTextPaint.setColor(Color.rgb(210, 90, 15));
            String message = anchorMoveState == 1
                    ? "text text text Roy Selection text"
                    : "text text Snap text text";
            canvas.drawText(message, getWidth() / 2f, 36f, chipTextPaint);
            chipTextPaint.setColor(Color.WHITE);
            chipTextPaint.setTextSize(28f);
            if (anchorSource != null) {
                PointF s = __SmartCadCanvasView_worldToScreen(anchorSource.x, anchorSource.y);
                float z = 16f;
                canvas.drawCircle(s.x, s.y, 13f, anchorPaint);
                canvas.drawLine(s.x - z, s.y, s.x + z, s.y, anchorPaint);
                canvas.drawLine(s.x, s.y - z, s.x, s.y + z, anchorPaint);
            }
        }
    }


    public boolean onTouchEvent(MotionEvent event) {
        // Never interfere with two-finger pan/zoom.
        if (event.getPointerCount() >= 2) {
            __SmartCadCanvasView_cancelSmartGesture();
            boolean handled = super.onTouchEvent(event);
            __SmartCadCanvasView_syncFromBaseIfNeeded();
            return handled;
        }

        final int action = event.getActionMasked();
        final float sx = event.getX();
        final float sy = event.getY();
        final float wx = __SmartCadCanvasView_screenToWorldXLocal(sx);
        final float wy = __SmartCadCanvasView_screenToWorldYLocal(sy);

        if (action == MotionEvent.ACTION_DOWN && !dimensionChip.isEmpty()
                && dimensionChip.contains(sx, sy)) {
            chipPressed = true;
            return true;
        }
        if (chipPressed) {
            if (action == MotionEvent.ACTION_UP) {
                chipPressed = false;
                if (dimensionChip.contains(sx, sy) && dimensionEditListener != null) {
                    dimensionEditListener.onDimensionEditRequested();
                }
            } else if (action == MotionEvent.ACTION_CANCEL) {
                chipPressed = false;
            }
            return true;
        }

        if (anchorMoveState > 0) {
            if (action == MotionEvent.ACTION_UP) __SmartCadCanvasView_handleAnchorTap(wx, wy);
            return true;
        }

        if (getTool() == TOOL_SELECT) {
            if (multiSelectMode) return __SmartCadCanvasView_handleMultiSelectTouch(event, wx, wy);
            return __SmartCadCanvasView_handleNormalSelectTouch(event, wx, wy);
        }

        boolean handled = super.onTouchEvent(event);
        if (action == MotionEvent.ACTION_UP) __SmartCadCanvasView_syncSelectionFromBase();
        return handled;
    }

    private boolean handleMultiSelectTouch(MotionEvent event, float wx, float wy) {
        int action = event.getActionMasked();
        if (action == MotionEvent.ACTION_DOWN) {
            boxStartX = boxEndX = event.getX();
            boxStartY = boxEndY = event.getY();
            pendingTapHit = coreFindHit(wx, wy);
            selectionBoxCandidate = pendingTapHit == null;
            selectionBoxActive = false;
            return true;
        }
        if (action == MotionEvent.ACTION_MOVE) {
            float d = __SmartCadCanvasView_distancePx(event.getX(), event.getY(), boxStartX, boxStartY);
            if (selectionBoxCandidate && d > TAP_SLOP_PX) {
                selectionBoxActive = true;
                boxEndX = event.getX();
                boxEndY = event.getY();
                invalidate();
            }
            return true;
        }
        if (action == MotionEvent.ACTION_UP) {
            if (selectionBoxActive) {
                boxEndX = event.getX();
                boxEndY = event.getY();
                __SmartCadCanvasView_selectByWindow(true);
            } else if (pendingTapHit != null) {
                __SmartCadCanvasView_toggleObjectOrGroup(pendingTapHit);
            }
            selectionBoxCandidate = false;
            selectionBoxActive = false;
            pendingTapHit = null;
            invalidate();
            return true;
        }
        if (action == MotionEvent.ACTION_CANCEL) {
            __SmartCadCanvasView_cancelSmartGesture();
            return true;
        }
        return true;
    }

    private boolean handleNormalSelectTouch(MotionEvent event, float wx, float wy) {
        int action = event.getActionMasked();

        if (action == MotionEvent.ACTION_DOWN) {
            boxStartX = boxEndX = event.getX();
            boxStartY = boxEndY = event.getY();

            // Selected control handles outrank body-hit. In particular, an Arc
            // center is intentionally off-curve and must not become empty-space
            // selection before the model-authority point gesture can finish.
            if (__SmartCadCanvasView_selectedControlHandleHit(wx, wy)) {
                selectionBoxCandidate = false;
                selectionBoxActive = false;
                pendingTapHit = null;
                boolean handled = super.onTouchEvent(event);
                __SmartCadCanvasView_syncSelectionFromBase();
                return handled;
            }

            Object hit = coreFindHit(wx, wy);

            List<Object> group = __SmartCadCanvasView_groupFor(hit);
            if (group != null && group.size() > 1) {
                __SmartCadCanvasView_setSelection(new ArrayList<>(group));
                groupDragging = true;
                groupDragUndoSaved = false;
                groupLastWorldX = wx;
                groupLastWorldY = wy;
                return true;
            }

            if (selectedObjects.size() > 1 && __SmartCadCanvasView_containsIdentity(selectedObjects, hit)) {
                groupDragging = true;
                groupDragUndoSaved = false;
                groupLastWorldX = wx;
                groupLastWorldY = wy;
                return true;
            }

            if (hit == null) {
                selectionBoxCandidate = true;
                selectionBoxActive = false;
                pendingTapHit = null;
                return true;
            }

            selectionBoxCandidate = false;
            selectionBoxActive = false;
            boolean handled = super.onTouchEvent(event);
            __SmartCadCanvasView_syncSelectionFromBase();
            return handled;
        }

        if (action == MotionEvent.ACTION_MOVE) {
            if (groupDragging) {
                float dx = wx - groupLastWorldX;
                float dy = wy - groupLastWorldY;
                if (!groupDragUndoSaved && __SmartCadCanvasView_distancePx(event.getX(), event.getY(), boxStartX, boxStartY) > 3f) {
                    coreSaveUndo();
                    groupDragUndoSaved = true;
                }
                if (groupDragUndoSaved) {
                    for (Object e : selectedObjects) __SmartCadCanvasView_translate(e, dx, dy);
                    groupLastWorldX = wx;
                    groupLastWorldY = wy;
                    invalidate();
                }
                return true;
            }

            if (selectionBoxCandidate) {
                float d = __SmartCadCanvasView_distancePx(event.getX(), event.getY(), boxStartX, boxStartY);
                if (d > TAP_SLOP_PX) {
                    selectionBoxActive = true;
                    boxEndX = event.getX();
                    boxEndY = event.getY();
                    invalidate();
                }
                return true;
            }

            return super.onTouchEvent(event);
        }

        if (action == MotionEvent.ACTION_UP) {
            if (groupDragging) {
                groupDragging = false;
                groupDragUndoSaved = false;
                invalidate();
                return true;
            }
            if (selectionBoxCandidate) {
                if (selectionBoxActive) {
                    boxEndX = event.getX();
                    boxEndY = event.getY();
                    __SmartCadCanvasView_selectByWindow(false);
                } else {
                    clearSmartSelection();
                }
                selectionBoxCandidate = false;
                selectionBoxActive = false;
                invalidate();
                return true;
            }
            boolean handled = super.onTouchEvent(event);
            __SmartCadCanvasView_syncSelectionFromBase();
            return handled;
        }

        if (action == MotionEvent.ACTION_CANCEL) {
            __SmartCadCanvasView_cancelSmartGesture();
            return true;
        }

        return super.onTouchEvent(event);
    }

    private void handleAnchorTap(float wx, float wy) {
        if (anchorMoveState == 1) {
            PointF p = __SmartCadCanvasView_nearestSelectedAnchor(wx, wy);
            if (p == null) p = __SmartCadCanvasView_selectionCenter();
            anchorSource = p;
            anchorMoveState = 2;
            __SmartCadCanvasView_notifyStatus("text selected; text text text Roy text/Center/Endpointtext text text text");
            invalidate();
            return;
        }

        if (anchorMoveState == 2 && anchorSource != null) {
            PointF target = __SmartCadCanvasView_snapExternal(wx, wy);
            coreSaveUndo();
            float dx = target.x - anchorSource.x;
            float dy = target.y - anchorSource.y;
            for (Object e : selectedObjects) __SmartCadCanvasView_translate(e, dx, dy);
            anchorMoveState = 0;
            anchorSource = null;
            __SmartCadCanvasView_notifyStatus("text Snap completed");
            invalidate();
        }
    }

    private void selectByWindow(boolean additive) {
        RectF screen = __SmartCadCanvasView_normalizedScreenRect(boxStartX, boxStartY, boxEndX, boxEndY);
        float wx1 = __SmartCadCanvasView_screenToWorldXLocal(screen.left);
        float wy1 = __SmartCadCanvasView_screenToWorldYLocal(screen.top);
        float wx2 = __SmartCadCanvasView_screenToWorldXLocal(screen.right);
        float wy2 = __SmartCadCanvasView_screenToWorldYLocal(screen.bottom);
        RectF world = new RectF(Math.min(wx1, wx2), Math.min(wy1, wy2),
                Math.max(wx1, wx2), Math.max(wy1, wy2));

        boolean leftToRight = boxEndX >= boxStartX;
        List<Object> found = new ArrayList<>();
        for (Object e : __SmartCadCanvasView_entities()) {
            if (!__SmartCadCanvasView_entityVisible(e) || __SmartCadCanvasView_entityConstruction(e)) continue;
            RectF b = __SmartCadCanvasView_entityBounds(e);
            if (b == null) continue;
            boolean match = leftToRight ? __SmartCadCanvasView_containsRect(world, b) : RectF.intersects(world, b);
            if (match) {
                List<Object> group = __SmartCadCanvasView_groupFor(e);
                if (group != null) __SmartCadCanvasView_addIdentityUnique(found, group);
                else __SmartCadCanvasView_addIdentityUnique(found, e);
            }
        }

        if (!additive) selectedObjects.clear();
        __SmartCadCanvasView_addIdentityUnique(selectedObjects, found);
        __SmartCadCanvasView_syncBaseSelectionWithSmart();
        __SmartCadCanvasView_notifyStatus(selectedObjects.isEmpty()
                ? "text text text Selection text"
                : selectedObjects.size() + " text selected");
    }

    private void toggleObjectOrGroup(Object hit) {
        List<Object> group = __SmartCadCanvasView_groupFor(hit);
        if (group != null) {
            boolean allSelected = true;
            for (Object e : group) if (!__SmartCadCanvasView_containsIdentity(selectedObjects, e)) allSelected = false;
            if (allSelected) __SmartCadCanvasView_removeIdentityAll(selectedObjects, group);
            else __SmartCadCanvasView_addIdentityUnique(selectedObjects, group);
        } else {
            if (__SmartCadCanvasView_containsIdentity(selectedObjects, hit)) __SmartCadCanvasView_removeIdentity(selectedObjects, hit);
            else selectedObjects.add(hit);
        }
        __SmartCadCanvasView_syncBaseSelectionWithSmart();
        __SmartCadCanvasView_notifyStatus(selectedObjects.isEmpty()
                ? "Selection text"
                : selectedObjects.size() + " text selected");
    }

    private void syncSelectionFromBase() {
        Object b = __SmartCadCanvasView_baseSelected();
        selectedObjects.clear();
        if (b != null) {
            List<Object> group = __SmartCadCanvasView_groupFor(b);
            if (group != null && !multiSelectMode) selectedObjects.addAll(group);
            else selectedObjects.add(b);
        }
        __SmartCadCanvasView_syncBaseSelectionWithSmart();
        invalidate();
    }

    private void syncFromBaseIfNeeded() {
        __SmartCadCanvasView_pruneSelection();
        if (selectedObjects.isEmpty()) {
            Object b = __SmartCadCanvasView_baseSelected();
            if (b != null) selectedObjects.add(b);
        }
    }

    private void setSelection(List<Object> objects) {
        selectedObjects.clear();
        __SmartCadCanvasView_addIdentityUnique(selectedObjects, objects);
        __SmartCadCanvasView_syncBaseSelectionWithSmart();
    }

    private void syncBaseSelectionWithSmart() {
        if (selectedObjects.size() == 1) __SmartCadCanvasView_setBaseSelected(selectedObjects.get(0));
        else __SmartCadCanvasView_setBaseSelected(null);
        invalidate();
    }

    private void pruneSelection() {
        List<Object> all = __SmartCadCanvasView_entities();
        Iterator<Object> it = selectedObjects.iterator();
        while (it.hasNext()) {
            Object e = it.next();
            if (!__SmartCadCanvasView_containsIdentity(all, e) || !__SmartCadCanvasView_entityVisible(e)) it.remove();
        }
        __SmartCadCanvasView_pruneGroups();
        if (selectedObjects.size() > 1) __SmartCadCanvasView_setBaseSelected(null);
    }

    private void pruneGroups() {
        List<Object> all = __SmartCadCanvasView_entities();
        Iterator<List<Object>> git = groups.iterator();
        while (git.hasNext()) {
            List<Object> g = git.next();
            Iterator<Object> eit = g.iterator();
            while (eit.hasNext()) if (!__SmartCadCanvasView_containsIdentity(all, eit.next())) eit.remove();
            if (g.size() < 2) git.remove();
        }
    }

    private List<Object> groupFor(Object entity) {
        if (entity == null) return null;
        __SmartCadCanvasView_pruneGroups();
        for (List<Object> g : groups) if (__SmartCadCanvasView_containsIdentity(g, entity)) return g;
        return null;
    }

    private PointF nearestSelectedAnchor(float wx, float wy) {
        float maxWorld = __SmartCadCanvasView_SNAP_RADIUS_PX / (__SmartCadCanvasView_PX_PER_MM * __SmartCadCanvasView_viewScale());
        PointF best = null;
        float bestD = Float.MAX_VALUE;
        for (Object e : selectedObjects) {
            for (PointF p : __SmartCadCanvasView_entitySnapPoints(e)) {
                float d = __SmartCadCanvasView_distanceWorld(wx, wy, p.x, p.y);
                if (d < bestD) { bestD = d; best = p; }
            }
            PointF c = __SmartCadCanvasView_entityCenter(e);
            if (c != null) {
                float d = __SmartCadCanvasView_distanceWorld(wx, wy, c.x, c.y);
                if (d < bestD) { bestD = d; best = c; }
            }
        }
        return bestD <= maxWorld * 1.4f ? best : __SmartCadCanvasView_selectionCenter();
    }

    private PointF snapExternal(float wx, float wy) {
        float radius = __SmartCadCanvasView_SNAP_RADIUS_PX / (__SmartCadCanvasView_PX_PER_MM * __SmartCadCanvasView_viewScale());
        PointF best = null;
        float bestD = Float.MAX_VALUE;

        for (Object e : __SmartCadCanvasView_entities()) {
            if (__SmartCadCanvasView_containsIdentity(selectedObjects, e) || !__SmartCadCanvasView_entityVisible(e) || __SmartCadCanvasView_entityConstruction(e)) continue;
            for (PointF p : __SmartCadCanvasView_entitySnapPoints(e)) {
                float d = __SmartCadCanvasView_distanceWorld(wx, wy, p.x, p.y);
                if (d <= radius && d < bestD) {
                    best = p;
                    bestD = d;
                }
            }
            PointF p = __SmartCadCanvasView_entityNearestPoint(e, wx, wy);
            if (p != null) {
                float d = __SmartCadCanvasView_distanceWorld(wx, wy, p.x, p.y);
                if (d <= radius * .70f && d < bestD) {
                    best = new PointF(p.x, p.y);
                    bestD = d;
                }
            }
        }

        if (best != null) return best;

        float gx = Math.round(wx / __SmartCadCanvasView_GRID_MM) * __SmartCadCanvasView_GRID_MM;
        float gy = Math.round(wy / __SmartCadCanvasView_GRID_MM) * __SmartCadCanvasView_GRID_MM;
        if (__SmartCadCanvasView_distanceWorld(wx, wy, gx, gy) <= radius * .58f) return new PointF(gx, gy);
        return new PointF(wx, wy);
    }

    private PointF selectionCenter() {
        RectF r = __SmartCadCanvasView_selectionBounds();
        if (r == null) return new PointF();
        return new PointF(r.centerX(), r.centerY());
    }

    private RectF selectionBounds() {
        RectF all = null;
        for (Object e : selectedObjects) {
            RectF b = __SmartCadCanvasView_entityBounds(e);
            if (b == null) continue;
            if (all == null) all = new RectF(b);
            else all.union(b);
        }
        return all;
    }

    private void cancelSmartGesture() {
        selectionBoxCandidate = false;
        selectionBoxActive = false;
        pendingTapHit = null;
        groupDragging = false;
        groupDragUndoSaved = false;
        chipPressed = false;
        invalidate();
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private List<Object> entities() {
        return (List<Object>) (List<?>) super.entities;
    }

    /** Snapshot for higher interaction layers; the owning list stays private to Smart. */
    protected final List<Object> smartSelectionSnapshot() {
        return new ArrayList<>(selectedObjects);
    }

    private Object baseSelected() { return selected; }

    private boolean selectedControlHandleHit(float wx, float wy) {
        Object current = __SmartCadCanvasView_baseSelected();
        if (!(current instanceof Entity)) return false;
        float radius = 18f / (__SmartCadCanvasView_PX_PER_MM * Math.max(.02f, __SmartCadCanvasView_viewScale()));
        float radius2 = radius * radius;
        List<ControlPoint> points = ((Entity) current).controlPoints();
        if (points == null) return false;
        for (ControlPoint point : points) {
            if (point == null) continue;
            float dx = wx - point.x;
            float dy = wy - point.y;
            if (dx * dx + dy * dy <= radius2) return true;
        }
        return false;
    }

    private void setBaseSelected(Object value) {
        selected = value instanceof Entity ? (Entity) value : null;
    }

    private boolean entityVisible(Object e) {
        return e instanceof Entity && coreIsVisible((Entity) e);
    }

    private boolean entityConstruction(Object e) {
        return e instanceof Entity && ((Entity) e).isConstruction();
    }

    private RectF entityBounds(Object e) {
        return e instanceof Entity ? new RectF(((Entity) e).bounds()) : null;
    }

    private PointF entityCenter(Object e) {
        if (!(e instanceof Entity)) return null;
        PointF p = ((Entity) e).center();
        return p == null ? null : new PointF(p.x, p.y);
    }

    private void translate(Object e, float dx, float dy) {
        if (e instanceof Entity) ((Entity) e).translate(dx, dy);
    }

    private Object entityCopy(Object e) {
        return e instanceof Entity ? ((Entity) e).copy() : null;
    }

    private Object entityOffsetCopy(Object e, float distance) {
        return e instanceof Entity ? ((Entity) e).offsetCopy(distance) : null;
    }

    private void entityRotate(Object e, float cx, float cy, float deg) {
        if (e instanceof Entity) ((Entity) e).rotate(cx, cy, deg);
    }

    private void entityScale(Object e, float cx, float cy, float factor) {
        if (e instanceof Entity) ((Entity) e).scale(cx, cy, factor);
    }

    private void entityMirrorHorizontal(Object e, float axis) {
        if (e instanceof Entity) ((Entity) e).mirrorHorizontal(axis);
    }

    private void entityMirrorVertical(Object e, float axis) {
        if (e instanceof Entity) ((Entity) e).mirrorVertical(axis);
    }

    private void entitySetLayer(Object e, String layer) {
        if (e instanceof Entity) ((Entity) e).setLayer(layer);
    }

    private void entitySetColor(Object e, int color) {
        if (e instanceof Entity) ((Entity) e).setColor(color);
    }

    private List<PointF> entitySnapPoints(Object e) {
        List<PointF> out = new ArrayList<>();
        if (!(e instanceof Entity)) return out;
        for (SnapPoint sp : ((Entity) e).snapPoints()) out.add(new PointF(sp.x, sp.y));
        return out;
    }

    private PointF entityNearestPoint(Object e, float wx, float wy) {
        if (!(e instanceof Entity)) return null;
        PointF p = ((Entity) e).nearestPoint(wx, wy);
        return p == null ? null : new PointF(p.x, p.y);
    }

    private float viewScale() { return super.viewScale; }
    private float offsetX() { return super.offsetX; }
    private float offsetY() { return super.offsetY; }

    private float screenToWorldXLocal(float sx) { return coreScreenToWorldX(sx); }
    private float screenToWorldYLocal(float sy) { return coreScreenToWorldY(sy); }

    private PointF worldToScreen(float wx, float wy) {
        float s = __SmartCadCanvasView_PX_PER_MM * __SmartCadCanvasView_viewScale();
        return new PointF(__SmartCadCanvasView_offsetX() + wx * s, __SmartCadCanvasView_offsetY() + wy * s);
    }

    private RectF worldRectToScreen(RectF r) {
        PointF a = __SmartCadCanvasView_worldToScreen(r.left, r.top);
        PointF b = __SmartCadCanvasView_worldToScreen(r.right, r.bottom);
        return new RectF(Math.min(a.x,b.x), Math.min(a.y,b.y), Math.max(a.x,b.x), Math.max(a.y,b.y));
    }

    private static RectF normalizedScreenRect(float x1, float y1, float x2, float y2) {
        return new RectF(Math.min(x1,x2), Math.min(y1,y2), Math.max(x1,x2), Math.max(y1,y2));
    }

    private static boolean containsRect(RectF outer, RectF inner) {
        return inner.left >= outer.left && inner.right <= outer.right
                && inner.top >= outer.top && inner.bottom <= outer.bottom;
    }

    private static float distancePx(float x1, float y1, float x2, float y2) {
        return (float)Math.hypot(x2-x1, y2-y1);
    }

    private static float distanceWorld(float x1, float y1, float x2, float y2) {
        return (float)Math.hypot(x2-x1, y2-y1);
    }

    private static float clamp(float v, float min, float max) {
        return Math.max(min, Math.min(max, v));
    }

    private static String format(float v) {
        return String.format(Locale.US, "%.2f", v);
    }

    private void notifyStatus(String text) {
        if (statusListener != null) statusListener.onStatus(text);
    }

    private static boolean containsIdentity(List<Object> list, Object value) {
        if (value == null) return false;
        for (Object x : list) if (x == value) return true;
        return false;
    }

    private static void removeIdentity(List<Object> list, Object value) {
        Iterator<Object> it = list.iterator();
        while (it.hasNext()) if (it.next() == value) { it.remove(); return; }
    }

    private static void removeIdentityAll(List<Object> list, List<Object> values) {
        for (Object value : values) __SmartCadCanvasView_removeIdentity(list, value);
    }

    private static void addIdentityUnique(List<Object> dst, Object value) {
        if (value != null && !__SmartCadCanvasView_containsIdentity(dst, value)) dst.add(value);
    }

    private static void addIdentityUnique(List<Object> dst, List<Object> values) {
        for (Object value : values) __SmartCadCanvasView_addIdentityUnique(dst, value);
    }

    private static boolean intersectsIdentity(List<Object> a, List<Object> b) {
        for (Object x : a) if (__SmartCadCanvasView_containsIdentity(b, x)) return true;
        return false;
    }

    private static boolean sameIdentitySet(List<Object> a, List<Object> b) {
        if (a.size() != b.size()) return false;
        for (Object x : a) if (!__SmartCadCanvasView_containsIdentity(b, x)) return false;
        return true;
    }

    private static int materialColorLocal(String m) {
        if (m == null) return Color.rgb(25,25,25);
        String s = m.trim().toUpperCase(Locale.US);
        if ("WOOD".equals(s) || "CHOB".equals(s) || "Wood".equals(m)) return Color.rgb(125,85,45);
        if ("MDF".equals(s)) return Color.rgb(145,110,70);
        if ("METAL".equals(s) || "Metal".equals(m)) return Color.rgb(90,100,110);
        if ("GLASS".equals(s) || "Glass".equals(m)) return Color.rgb(80,150,175);
        return Color.rgb(25,25,25);
    }

    private static String normalizeDigits(String s) {
        if (s == null) return "";
        StringBuilder b = new StringBuilder(s.length());
        for (int i=0;i<s.length();i++) {
            char c=s.charAt(i);
            b.append(c);
        }
        return b.toString();
    }


    // ===== flattened from AdvancedCadCanvasView =====


    private Field smartSelectedField;
    private Field entitiesField;
    private Field baseSelectedField;
    private Method saveUndoMethod;



    private void initAdvancedReflection() {
        try {
            smartSelectedField = SmartCadCanvasView.class.getDeclaredField("selectedObjects");
            smartSelectedField.setAccessible(true);
            __AdvancedCadCanvasView_entitiesField = CadCanvasView.class.getDeclaredField("entities");
            __AdvancedCadCanvasView_entitiesField.setAccessible(true);
            baseSelectedField = CadCanvasView.class.getDeclaredField("selected");
            baseSelectedField.setAccessible(true);
            __AdvancedCadCanvasView_saveUndoMethod = CadCanvasView.class.getDeclaredMethod("saveUndo");
            __AdvancedCadCanvasView_saveUndoMethod.setAccessible(true);
        } catch (Exception ignored) {
        }
    }

    /** Trim crossing line segments to their intersection, keeping the longer side of each line. */
    public String trimSelectedLines() {
        List<Object> pair = __AdvancedCadCanvasView_twoSelectedLines();
        if (pair == null) return "Trim requires exactly two selected lines.";
        LineData a = __AdvancedCadCanvasView_readLine(pair.get(0));
        LineData b = __AdvancedCadCanvasView_readLine(pair.get(1));
        PointF p = __AdvancedCadCanvasView_infiniteIntersection(a, b);
        if (p == null) return "The selected lines are parallel; Trim cannot find an intersection.";
        if (!__AdvancedCadCanvasView_pointOnSegment(p, a, 0.05f) || !__AdvancedCadCanvasView_pointOnSegment(p, b, 0.05f))
            return "The selected segments do not cross; use Extend first.";

        __AdvancedCadCanvasView_saveUndo();
        __AdvancedCadCanvasView_keepFarSideAt(pair.get(0), a, p);
        __AdvancedCadCanvasView_keepFarSideAt(pair.get(1), b, p);
        invalidate();
        return "Trim completed — both lines were shortened to the intersection.";
    }

    /** Extends only the selected lines that do not currently reach the common infinite-line intersection. */
    public String extendSelectedLines() {
        List<Object> pair = __AdvancedCadCanvasView_twoSelectedLines();
        if (pair == null) return "Extend requires exactly two selected lines.";
        LineData a = __AdvancedCadCanvasView_readLine(pair.get(0));
        LineData b = __AdvancedCadCanvasView_readLine(pair.get(1));
        PointF p = __AdvancedCadCanvasView_infiniteIntersection(a, b);
        if (p == null) return "The selected lines are parallel and cannot be extended to an intersection.";

        boolean aHas = __AdvancedCadCanvasView_pointOnSegment(p, a, 0.05f);
        boolean bHas = __AdvancedCadCanvasView_pointOnSegment(p, b, 0.05f);
        if (aHas && bHas) return "Both lines already reach the intersection; use Trim if you need to shorten them.";

        __AdvancedCadCanvasView_saveUndo();
        if (!aHas) __AdvancedCadCanvasView_moveNearestEndpoint(pair.get(0), a, p);
        if (!bHas) __AdvancedCadCanvasView_moveNearestEndpoint(pair.get(1), b, p);
        invalidate();
        return "Extend completed — the selected lines now meet at the intersection.";
    }

    /** Creates a straight chamfer between two selected line directions. */
    public String chamferSelectedLines(float setback) {
        if (setback <= 0f) return "Chamfer distance must be greater than zero.";
        List<Object> pair = __AdvancedCadCanvasView_twoSelectedLines();
        if (pair == null) return "Chamfer requires exactly two selected lines.";
        LineData a = __AdvancedCadCanvasView_readLine(pair.get(0));
        LineData b = __AdvancedCadCanvasView_readLine(pair.get(1));
        PointF corner = __AdvancedCadCanvasView_infiniteIntersection(a, b);
        if (corner == null) return "Parallel lines cannot create a chamfer.";

        Branch ba = __AdvancedCadCanvasView_keptBranch(a, corner);
        Branch bb = __AdvancedCadCanvasView_keptBranch(b, corner);
        if (ba.length <= setback || bb.length <= setback)
            return "Chamfer distance exceeds the available length on one of the selected lines.";

        PointF pa = __AdvancedCadCanvasView_add(corner, __AdvancedCadCanvasView_mul(ba.u, setback));
        PointF pb = __AdvancedCadCanvasView_add(corner, __AdvancedCadCanvasView_mul(bb.u, setback));

        __AdvancedCadCanvasView_saveUndo();
        __AdvancedCadCanvasView_setEndpoint(pair.get(0), ba.nearIndex, pa);
        __AdvancedCadCanvasView_setEndpoint(pair.get(1), bb.nearIndex, pb);
        Object bridge = __AdvancedCadCanvasView_newLine(pa.x, pa.y, pb.x, pb.y, pair.get(0));
        if (bridge != null) __AdvancedCadCanvasView_entities().add(bridge);
        invalidate();
        return "Chamfer = " + __AdvancedCadCanvasView_fmt(setback) + " mm created";
    }

    /** Creates a tangent circular fillet between two selected line directions. */
    public String filletSelectedLines(float radius) {
        if (radius <= 0f) return "Fillet radius must be greater than zero.";
        List<Object> pair = __AdvancedCadCanvasView_twoSelectedLines();
        if (pair == null) return "Fillet requires exactly two selected lines.";
        LineData a = __AdvancedCadCanvasView_readLine(pair.get(0));
        LineData b = __AdvancedCadCanvasView_readLine(pair.get(1));
        PointF corner = __AdvancedCadCanvasView_infiniteIntersection(a, b);
        if (corner == null) return "Parallel lines cannot create a fillet.";

        Branch ba = __AdvancedCadCanvasView_keptBranch(a, corner);
        Branch bb = __AdvancedCadCanvasView_keptBranch(b, corner);
        float dot = __AdvancedCadCanvasView_clamp(ba.u.x * bb.u.x + ba.u.y * bb.u.y, -1f, 1f);
        double theta = Math.acos(dot);
        double degrees = Math.toDegrees(theta);
        if (degrees < 5.0 || degrees > 175.0)
            return "The angle between the selected lines is not suitable for a fillet.";

        float tangent = (float)(radius / Math.tan(theta / 2.0));
        if (tangent <= 0f || tangent >= ba.length || tangent >= bb.length)
            return "Fillet radius exceeds the available length on one of the selected lines.";

        PointF pa = __AdvancedCadCanvasView_add(corner, __AdvancedCadCanvasView_mul(ba.u, tangent));
        PointF pb = __AdvancedCadCanvasView_add(corner, __AdvancedCadCanvasView_mul(bb.u, tangent));
        PointF bisector = __AdvancedCadCanvasView_unit(ba.u.x + bb.u.x, ba.u.y + bb.u.y);
        float centerDistance = (float)(radius / Math.sin(theta / 2.0));
        PointF center = __AdvancedCadCanvasView_add(corner, __AdvancedCadCanvasView_mul(bisector, centerDistance));

        float start = __AdvancedCadCanvasView_angleDeg(center, pa);
        float end = __AdvancedCadCanvasView_angleDeg(center, pb);
        float sweep = __AdvancedCadCanvasView_shortestSweep(start, end);

        __AdvancedCadCanvasView_saveUndo();
        __AdvancedCadCanvasView_setEndpoint(pair.get(0), ba.nearIndex, pa);
        __AdvancedCadCanvasView_setEndpoint(pair.get(1), bb.nearIndex, pb);
        Object arc = __AdvancedCadCanvasView_newArc(center.x, center.y, radius, start, sweep, pair.get(0));
        if (arc != null) __AdvancedCadCanvasView_entities().add(arc);
        invalidate();
        return "Fillet R " + __AdvancedCadCanvasView_fmt(radius) + " mm created";
    }

    /** Joins two almost-collinear lines that touch or have only a small gap. */
    public String joinSelectedLines() {
        List<Object> pair = __AdvancedCadCanvasView_twoSelectedLines();
        if (pair == null) return "Join requires exactly two selected lines.";
        LineData a = __AdvancedCadCanvasView_readLine(pair.get(0));
        LineData b = __AdvancedCadCanvasView_readLine(pair.get(1));
        if (a == null || b == null) return "The selected geometry is not a valid pair of lines.";

        PointF da = __AdvancedCadCanvasView_unit(a.x2-a.x1, a.y2-a.y1);
        PointF db = __AdvancedCadCanvasView_unit(b.x2-b.x1, b.y2-b.y1);
        float cross = Math.abs(da.x*db.y-da.y*db.x);
        if (cross > 0.025f) return "The selected lines are not collinear enough to join.";

        EndpointPair nearest = __AdvancedCadCanvasView_nearestEndpointPair(a, b);
        if (nearest.distance > 5f) return "The gap between the selected lines is greater than 5 mm.";

        PointF farA = nearest.aIndex == 0 ? new PointF(a.x2,a.y2) : new PointF(a.x1,a.y1);
        PointF farB = nearest.bIndex == 0 ? new PointF(b.x2,b.y2) : new PointF(b.x1,b.y1);

        __AdvancedCadCanvasView_saveUndo();
        __AdvancedCadCanvasView_writeLine(pair.get(0), farA.x, farA.y, farB.x, farB.y);
        __AdvancedCadCanvasView_entities().remove(pair.get(1));
        List<Object> one = new ArrayList<>();
        one.add(pair.get(0));
        __AdvancedCadCanvasView_setSmartSelection(one);
        invalidate();
        return "The selected lines were joined into one line.";
    }


    public String executeCommand(String raw) {
        if (raw == null) return "";
        String s = __AdvancedCadCanvasView_normalizeDigits(raw).trim().replace(',', ' ');
        if (s.isEmpty()) return "";
        String[] a = s.split("\\s+");
        String cmd = a[0].toUpperCase(Locale.US);
        try {
            if ("TR".equals(cmd) || "TRIM".equals(cmd)) return trimSelectedLines();
            if ("EX".equals(cmd) || "EXTEND".equals(cmd)) return extendSelectedLines();
            if ("F".equals(cmd) || "FILLET".equals(cmd)) {
                if (a.length < 2) return "FILLET requires a radius.";
                return filletSelectedLines(Float.parseFloat(a[1]));
            }
            if ("CHA".equals(cmd) || "CHAMFER".equals(cmd)) {
                if (a.length < 2) return "CHAMFER requires a distance.";
                return chamferSelectedLines(Float.parseFloat(a[1]));
            }
            if ("J".equals(cmd) || "JOIN".equals(cmd)) return joinSelectedLines();
        } catch (Exception e) {
            return "Number format is invalid";
        }
        return __CadCanvasView_executeCommand(s);
    }

