    private Branch keptBranch(LineData d, PointF corner) {
        float d1 = __AdvancedCadCanvasView_dist(d.x1,d.y1,corner.x,corner.y);
        float d2 = __AdvancedCadCanvasView_dist(d.x2,d.y2,corner.x,corner.y);
        if (d1 <= d2) {
            PointF u = __AdvancedCadCanvasView_unit(d.x2-corner.x, d.y2-corner.y);
            return new Branch(0,u,d2);
        } else {
            PointF u = __AdvancedCadCanvasView_unit(d.x1-corner.x, d.y1-corner.y);
            return new Branch(1,u,d1);
        }
    }

