    private void clearDirectionalConstraints(Object line) {
        try {
            if (parentAxisLocksField != null) {
                Object map = parentAxisLocksField.get(this);
                if (map instanceof Map) ((Map<?, ?>) map).remove(line);
            }
            if (parentRelationsField != null) {
                Object list = parentRelationsField.get(this);
                if (list instanceof List) {
                    Iterator<?> it = ((List<?>) list).iterator();
                    while (it.hasNext()) {
                        Object rel = it.next();
                        Object a = __ParametricSketchCanvasView_getObjectField(rel, "a");
                        Object b = __ParametricSketchCanvasView_getObjectField(rel, "b");
                        if (a == line || b == line) it.remove();
                    }
                }
            }
        } catch (Exception ignored) {}
    }

    private int connectedEndpointIndex(Object line) {
        for (PointOnLineLink link : pointOnLineLinks) if (link.endpoint.line == line) return link.endpoint.index;
        try {
            Object list = parentCoincidenceField == null ? null : parentCoincidenceField.get(this);
            if (list instanceof List) {
                for (Object c : (List<?>) list) {
                    Object a = __ParametricSketchCanvasView_getObjectField(c, "a"), b = __ParametricSketchCanvasView_getObjectField(c, "b");
                    Object al = __ParametricSketchCanvasView_getObjectField(a, "line"), bl = __ParametricSketchCanvasView_getObjectField(b, "line");
                    if (al == line) return __ParametricSketchCanvasView_getIntField(a, "index", -1);
                    if (bl == line) return __ParametricSketchCanvasView_getIntField(b, "index", -1);
                }
            }
        } catch (Exception ignored) {}
        return -1;
    }

    private int commonEndpointIndex(Object moving, Object fixed) {
        for (int mi = 0; mi < 2; mi++) {
            PointF mp = __ParametricSketchCanvasView_endpoint(moving, mi);
            if (mp == null) continue;
            for (int fi = 0; fi < 2; fi++) {
                PointF fp = __ParametricSketchCanvasView_endpoint(fixed, fi);
                if (fp != null && __ParametricSketchCanvasView_dist(mp.x, mp.y, fp.x, fp.y) <= 0.15f) return mi;
            }
        }
        return -1;
    }

    private void setLineAngle(Object line, float angle, int pivotIndex) {
        PointF a = __ParametricSketchCanvasView_endpoint(line, 0), b = __ParametricSketchCanvasView_endpoint(line, 1);
        if (a == null || b == null) return;
        float len = __ParametricSketchCanvasView_dist(a.x, a.y, b.x, b.y);
        double r = Math.toRadians(angle);
        float vx = len * (float) Math.cos(r), vy = len * (float) Math.sin(r);
        if (pivotIndex == 0) {
            __ParametricSketchCanvasView_setEndpoint(line, 1, a.x + vx, a.y + vy);
        } else if (pivotIndex == 1) {
            __ParametricSketchCanvasView_setEndpoint(line, 0, b.x - vx, b.y - vy);
        } else {
            float cx = (a.x + b.x) / 2f, cy = (a.y + b.y) / 2f;
            __ParametricSketchCanvasView_setEndpoint(line, 0, cx - vx / 2f, cy - vy / 2f);
            __ParametricSketchCanvasView_setEndpoint(line, 1, cx + vx / 2f, cy + vy / 2f);
        }
    }

