    public boolean onTouchEvent(MotionEvent original) {
        int action = original.getActionMasked();
        float sx = original.getX(), sy = original.getY();

        if (__ParametricSketchCanvasView_handleUiChipTouch(original)) return true;

        if (original.getPointerCount() >= 2) {
            lockedGesture = false;
            boolean handled = __ShaprStyleCadCanvasView_onTouchEvent(original);
            if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) __ParametricSketchCanvasView_enforcePointLinks();
            return handled;
        }

        if (__ParametricSketchCanvasView_activeSketchLocked() && getTool() != TOOL_SELECT && action == MotionEvent.ACTION_DOWN) {
            super.setTool(TOOL_SELECT);
            __ParametricSketchCanvasView_toast("Sketch text Lock text");
            return true;
        }

        if (lockedGesture) {
            if (action == MotionEvent.ACTION_UP || action == MotionEvent.ACTION_CANCEL) {
                lockedGesture = false;
                dispatchWorkspaceState();
            }
            return true;
        }

        if (getTool() == TOOL_SELECT && action == MotionEvent.ACTION_DOWN) {
            float wx = __ParametricSketchCanvasView_screenToWorldX(sx), wy = __ParametricSketchCanvasView_screenToWorldY(sy);
            Object hit = __ParametricSketchCanvasView_findHit(wx, wy);
            if (__ParametricSketchCanvasView_isEffectiveEntityLocked(hit)) {
                __ParametricSketchCanvasView_selectOnly(hit);
                lockedGesture = true;
                __ParametricSketchCanvasView_toast("text Geometry Lock text; Selection text but Transform text");
                return true;
            }
            if (__ParametricSketchCanvasView_isEffectiveSelectionLocked()) {
                PointF c = __ParametricSketchCanvasView_selectionCenter(__ParametricSketchCanvasView_selectionObjects());
                if (c != null) {
                    PointF cs = __ParametricSketchCanvasView_worldToScreen(c.x, c.y);
                    if (__ParametricSketchCanvasView_dist(sx, sy, cs.x, cs.y) <= 115f) {
                        lockedGesture = true;
                        __ParametricSketchCanvasView_toast("Selection Lock text");
                        return true;
                    }
                }
            }
        }

        int toolBefore = getTool();
        MotionEvent event = original;
        MotionEvent adjusted = null;
        if (toolBefore == TOOL_LINE && (action == MotionEvent.ACTION_DOWN || action == MotionEvent.ACTION_UP)) {
            adjusted = __ParametricSketchCanvasView_adjustLinePointer(original);
            if (adjusted != null) event = adjusted;
        }

        boolean handled = __ShaprStyleCadCanvasView_onTouchEvent(event);
        if (adjusted != null) adjusted.recycle();

        if (action == MotionEvent.ACTION_UP && toolBefore == TOOL_LINE && getTool() == TOOL_SELECT) {
            Object made = __ParametricSketchCanvasView_selectedObject();
            if (__ParametricSketchCanvasView_isLine(made)) __ParametricSketchCanvasView_detectPointOnLineLinks(made);
        }

        if (!isModelEndpointConstraintAuthorityEnabled()) __ParametricSketchCanvasView_enforcePointLinks();
        invalidate();
        return handled;
    }

    private boolean handleUiChipTouch(MotionEvent event) {
        int action = event.getActionMasked();
        float x = event.getX(), y = event.getY();
        if (action == MotionEvent.ACTION_DOWN) {
            if (sketchChip.contains(x,y)) { pressedChip = 1; return true; }
            if (constraintsChip.contains(x,y)) { pressedChip = 2; return true; }
            if (!angleChip.isEmpty() && angleChip.contains(x,y)) { pressedChip = 3; return true; }
            if (!lockChip.isEmpty() && lockChip.contains(x,y)) { pressedChip = 4; return true; }
            return false;
        }
        if (pressedChip != 0) {
            if (action == MotionEvent.ACTION_UP) {
                int p = pressedChip; pressedChip = 0;
                if (p == 1 && sketchChip.contains(x,y)) __ParametricSketchCanvasView_showSketchManager();
                else if (p == 2 && constraintsChip.contains(x,y)) __ParametricSketchCanvasView_showConstraintsMenu();
                else if (p == 3 && angleChip.contains(x,y)) __ParametricSketchCanvasView_showAngleEditor();
                else if (p == 4 && lockChip.contains(x,y)) __ParametricSketchCanvasView_toast(toggleSelectedLock());
            } else if (action == MotionEvent.ACTION_CANCEL) pressedChip = 0;
            return true;
        }
        return false;
    }

