    // ------------------------------------------------------------------
    // Difficult real-workflow regression model
    // ------------------------------------------------------------------

    /**
     * Recreates the difficult sketch/setup stage of Shapr3D's official Action
     * Camera Mount tutorial using ChobYar primitives and constraints. Explicit
     * tutorial values are preserved: 9, 4.5, 3, 6, 1.5 mm and 135 degrees.
     * ChobYar command input is cm, therefore the values below are divided by 10.
     */
    public String buildActionMountLab() {
        if (labBuilt) return getResources().getString(R.string.shapr_lab_already_created);

        createSketchSpace("LAB • Action Mount");

        Object axis = __ShaprLabCanvasView_make("LINE 0 -0.30 0 1.65");
        Object base = __ShaprLabCanvasView_make("LINE -0.90 0 0.90 0");
        Object baseOffset = __ShaprLabCanvasView_make("LINE -0.90 0.30 0.90 0.30");

        Object li = __ShaprLabCanvasView_make("LINE -0.90 0 -0.90 0.60");
        Object la = __ShaprLabCanvasView_make("LINE -0.90 0.60 -1.20 0.90");
        Object lo = __ShaprLabCanvasView_make("LINE -1.20 0.90 -1.20 1.35");
        Object lOffset = __ShaprLabCanvasView_make("LINE -0.75 0 -0.75 0.60");

        Object ri = __ShaprLabCanvasView_make("LINE 0.90 0 0.90 0.60");
        Object ra = __ShaprLabCanvasView_make("LINE 0.90 0.60 1.20 0.90");
        Object ro = __ShaprLabCanvasView_make("LINE 1.20 0.90 1.20 1.35");
        Object rOffset = __ShaprLabCanvasView_make("LINE 0.75 0 0.75 0.60");

        Object rib = __ShaprLabCanvasView_make("LINE 0 0 0 0.60");
        Object leftBoss = __ShaprLabCanvasView_make("CIRCLE -1.50 1.35 0.30");
        Object rightBoss = __ShaprLabCanvasView_make("CIRCLE 1.50 1.35 0.30");

        // Directional constraints.
        __ShaprLabCanvasView_setSelection(axis); applyHorizontalVerticalConstraint();
        __ShaprLabCanvasView_setSelection(base, baseOffset); applyHorizontalVerticalConstraint();
        __ShaprLabCanvasView_setSelection(li, lo, lOffset, ri, ro, rOffset, rib); applyHorizontalVerticalConstraint();

        // Driving angular dimensions from the tutorial.
        __ShaprLabCanvasView_setSelection(la); setSelectedLineAngle(135f);
        __ShaprLabCanvasView_setSelection(ra); setSelectedLineAngle(45f);

        // Persistent symmetry, equality, midpoint and tangency.
        __ShaprLabCanvasView_setSelection(la, ra, axis); applySymmetryConstraint();
        __ShaprLabCanvasView_setSelection(leftBoss, rightBoss); applyEqualConstraint();
        __ShaprLabCanvasView_setSelection(rib, base); applyMidpointConstraint();
        __ShaprLabCanvasView_setSelection(lo, leftBoss); applyTangentConstraint();
        __ShaprLabCanvasView_setSelection(ro, rightBoss); applyTangentConstraint();

        // Stable driving axis.
        __ShaprLabCanvasView_setSelection(axis); toggleSelectedLock();

        // A second independent sketch emulates the later relief/projection stage.
        createSketchSpace("LAB • Relief");
        Object reliefAxis = __ShaprLabCanvasView_make("LINE 0 1.55 0 2.15");
        Object rt = __ShaprLabCanvasView_make("LINE -0.40 1.70 0.40 1.70");
        Object rl = __ShaprLabCanvasView_make("LINE -0.40 1.70 -0.70 2.00");
        Object rr = __ShaprLabCanvasView_make("LINE 0.40 1.70 0.70 2.00");
        Object rb = __ShaprLabCanvasView_make("LINE -0.70 2.00 0.70 2.00");
        __ShaprLabCanvasView_setSelection(reliefAxis, rt, rb); applyHorizontalVerticalConstraint();
        __ShaprLabCanvasView_setSelection(rl); setSelectedLineAngle(135f);
        __ShaprLabCanvasView_setSelection(rr); setSelectedLineAngle(45f);
        __ShaprLabCanvasView_setSelection(rl, rr, reliefAxis); applySymmetryConstraint();
        __ShaprLabCanvasView_setSelection(reliefAxis); toggleSelectedLock();

        // Back to the driving sketch; both sketches remain independently managed.
        int n = __ShaprLabCanvasView_sketchCount();
        if (n >= 2) switchSketchSpace(n - 2);
        __ShaprLabCanvasView_clearSelection();
        fitAll();
        labBuilt = true;
        invalidate();
        Toast.makeText(getContext(),
                getResources().getString(R.string.shapr_lab_created_toast),
                Toast.LENGTH_LONG).show();
        return "Action Mount LAB created";
    }

    private Object make(String command) {
        executeCommand(command);
        return __ShaprLabCanvasView_selectedObject();
    }

