    private void drawLabChip(Canvas canvas) {
        float w=labBuilt?155f:190f;
        float right=getWidth()-12f;
        labChip.set(right-w,204f,right,204f+CHIP_H);
        canvas.drawRoundRect(labChip,14f,14f,chipFill);
        canvas.drawRoundRect(labChip,14f,14f,chipStroke);
        canvas.drawText(labBuilt?"LAB • Action Mount":getResources().getString(R.string.shapr_lab_chip_build),labChip.centerX(),labChip.centerY()+7f,chipText);
    }

    private void drawRelationBadges(Canvas canvas) {
        for(EqualRelation r:equalRelations)for(Object e:r.items)__ShaprLabCanvasView_badge(canvas,e,"=");
        for(SymmetryRelation r:symmetryRelations){__ShaprLabCanvasView_badge(canvas,r.source,"S");__ShaprLabCanvasView_badge(canvas,r.mirror,"S");}
        for(MidpointRelation r:midpointRelations)__ShaprLabCanvasView_badge(canvas,r.endpointLine,"M");
        for(TangentRelation r:tangentRelations)__ShaprLabCanvasView_badge(canvas,r.line,"T");
    }

    private void badge(Canvas canvas,Object e,String text) {
        PointF c=__ShaprLabCanvasView_center(e);
        if(c==null)return;
        PointF s=__ShaprLabCanvasView_worldToScreen(c.x,c.y);
        canvas.drawText(text,s.x+18f,s.y-18f,relationText);
    }


    public boolean onTouchEvent(MotionEvent event) {
        int a=event.getActionMasked();
        float x=event.getX(),y=event.getY();
        if(a==MotionEvent.ACTION_DOWN&&labChip.contains(x,y)){labPressed=true;return true;}
        if(labPressed){
            if(a==MotionEvent.ACTION_UP){labPressed=false;if(labChip.contains(x,y))__ShaprLabCanvasView_showLabMenu();}
            else if(a==MotionEvent.ACTION_CANCEL)labPressed=false;
            return true;
        }
        boolean handled=__ChobYarShaprCanvasView_onTouchEvent(event);
        if(a==MotionEvent.ACTION_UP||a==MotionEvent.ACTION_CANCEL)invalidate();
        return handled;
    }

    private void showLabMenu() {
        String[] items={
                labBuilt?getResources().getString(R.string.shapr_lab_menu_created):"Create Action Mount LAB",
                getResources().getString(R.string.shapr_lab_equal),
                "S Symmetry / Symmetry",
                "M Midpoint / Midpoint Line",
                "T Tangent / Tangent",
                "Fit All"
        };
        new AlertDialog.Builder(getContext())
                .setTitle("ChobYar • Shapr LAB")
                .setMessage(getResources().getString(R.string.shapr_lab_message))
                .setItems(items,(d,w)->{
                    String result;
                    if(w==0)result=buildActionMountLab();
                    else if(w==1)result=applyEqualConstraint();
                    else if(w==2)result=applySymmetryConstraint();
                    else if(w==3)result=applyMidpointConstraint();
                    else if(w==4)result=applyTangentConstraint();
                    else{fitAll();result="Fit All";}
                    Toast.makeText(getContext(),result,Toast.LENGTH_SHORT).show();
                })
                .setNegativeButton("Close",null).show();
    }


    public void clearAll() {
        __ChobYarShaprCanvasView_clearAll();
        __ShaprLabCanvasView_clearRelations();
        labBuilt=false;
    }


    public void undo() {
        __ChobYarShaprCanvasView_undo();
        // Base undo clones entity instances; identity relations must not point
        // at pre-undo objects.
        __ShaprLabCanvasView_clearRelations();
        labBuilt=false;
    }

    private void clearRelations() {
        equalRelations.clear(); symmetryRelations.clear(); midpointRelations.clear(); tangentRelations.clear();
    }

