    public void showSolidManager() {
        String selected = selectedBody == null ? "No body selected" : selectedBody.name;
        String face = selectedFace == null ? "No face selected" : "Face selected — Ready Sketch";
        String[] items = {
                "⬆ Extrude / text Sketch text text Body",
                "▣ Bodies ("+bodies.size()+")",
                "▱ Sketch Roy Face selected",
                "∪ Union / text",
                "− Subtract / text",
                "∩ Intersect / text",
                "⌫ Delete Body selected",
                "↶ Undo text Solid",
                is3DOverview()?"□ text text Sketch 2D":"◇ Show 3D"
        };
        new AlertDialog.Builder(getContext())
                .setTitle("Solid 3D")
                .setMessage(selected+"\n"+face+" \n  \n text Selection Body text Face text 3D View Roy text text.")
                .setItems(items,(d,w)->{
                    if(w==0)__SolidCadCanvasView_showExtrudeDialog();
                    else if(w==1)__SolidCadCanvasView_showBodiesDialog();
                    else if(w==2)__SolidCadCanvasView_toast(sketchOnSelectedFace());
                    else if(w==3)__SolidCadCanvasView_startBoolean("UNION");
                    else if(w==4)__SolidCadCanvasView_startBoolean("SUBTRACT");
                    else if(w==5)__SolidCadCanvasView_startBoolean("INTERSECT");
                    else if(w==6)__SolidCadCanvasView_toast(deleteSelectedBody());
                    else if(w==7)__SolidCadCanvasView_toast(undoSolid());
                    else __SolidCadCanvasView_toast(toggle3DOverview());
                })
                .setNegativeButton("Close",null)
                .show();
    }

    public String extrudeSelectedBody(float heightCm) {
        if (Math.abs(heightCm) < 0.0001f) return "Height Extrude text text text";
        ProfileData profile = __SolidCadCanvasView_profileFromSelection();
        if (profile == null || profile.points.size() < 3)
            return "text Face text Selection text; Rectangle, Circle, Polygon text text Linetext text";
        Geometry3D.Plane3D plane = __SolidCadCanvasView_planeForLayer(profile.layer);
        SolidCSG solid = SolidCSG.extrude(profile.points, plane, heightCm*10f);
        if (solid.isEmpty()) return "Create Body text text";
        __SolidCadCanvasView_saveSolidUndo();
        SolidBody body = new SolidBody(bodySerial,"Body "+bodySerial,solid);
        bodySerial++;
        bodies.add(body);
        selectedBody=body;
        selectedFace=null;
        __SolidCadCanvasView_clearSubSelection();
        __SolidCadCanvasView_setOverview(true);
        // A sketch can be heavily zoomed or panned. Reusing that camera made a
        // valid extrusion look enormous, clipped or completely off-screen.
        // Fit after layout/draw has switched to the 3D workspace so bounds are
        // evaluated against the real body and the final viewport size.
        post(this::fitAll);
        invalidate();
        return body.name+" created | Extrude = "+__SolidCadCanvasView_fmt(heightCm*10f)+" mm";
    }

