    /**
     * Apply an exact millimetre value without tearing down the active preview.
     * Keeping this mutation on the canvas (instead of in the dialog) makes the
     * preview, workspace state and Commit button update as one operation.
     */
    public boolean setInteractiveExtrudeHeightMm(float millimeters){
        if(!extrudeSessionActive||Float.isNaN(millimeters)||Float.isInfinite(millimeters))return false;
        if(Math.abs(millimeters)<.1f)millimeters=millimeters<0f?-.1f:.1f;
        extrudePreviewHeightMm=millimeters;
        __SolidCadCanvasView_rebuildExtrudePreview(true);
        dispatchWorkspaceState();
        return extrudePreview!=null&&!extrudePreview.isEmpty();
    }

    public void showInteractiveExtrudeHeightEditor(){__SolidCadCanvasView_promptInteractiveExtrudeValue();}

    public String commitInteractiveExtrude(){
        if(!extrudeSessionActive)return "Extrude text text";
        float mm=extrudePreviewHeightMm;__SolidCadCanvasView_clearExtrudeSession();
        String result=extrudeSelectedBody(mm/10f);dispatchWorkspaceState();return result;
    }

    public void cancelInteractiveExtrude(){__SolidCadCanvasView_clearExtrudeSession();dispatchWorkspaceState();}

    private void rebuildExtrudePreview(boolean fit){
        if(!extrudeSessionActive||extrudeSessionProfile==null||extrudeSessionPlane==null)return;
        if(Math.abs(extrudePreviewHeightMm)<.1f)extrudePreviewHeightMm=extrudePreviewHeightMm<0f?-.1f:.1f;
        extrudePreview=SolidCSG.extrude(extrudeSessionProfile.points,extrudeSessionPlane,extrudePreviewHeightMm);
        if(fit)__SolidCadCanvasView_fitPreview();invalidate();
    }

    private void promptInteractiveExtrudeValue(){
        if(!extrudeSessionActive)return;
        LinearLayout box=new LinearLayout(getContext());box.setOrientation(LinearLayout.VERTICAL);
        int pad=Math.round(18f*getResources().getDisplayMetrics().density);box.setPadding(pad,pad/2,pad,pad/2);
        EditText exact=new EditText(getContext());exact.setSingleLine();exact.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);
        exact.setText(__SolidCadCanvasView_fmt(extrudePreviewHeightMm)+"mm");exact.setSelectAllOnFocus(true);box.addView(exact);
        new AlertDialog.Builder(getContext()).setTitle("Extrude • mm")
                .setMessage("text text text text text text text.")
                .setView(box).setPositiveButton("Apply",(d,w)->{
                    try{
                        if(!setInteractiveExtrudeHeightMm(__SolidCadCanvasView_parseLengthInput(exact.getText().toString())))
                            __SolidCadCanvasView_toast("Preview Extrude text text");
                    }
                    catch(Exception e){__SolidCadCanvasView_toast("Dimension is invalid • text: 20 mm");}
                }).setNegativeButton("Cancel",null).show();
    }

    private float parseLengthInput(String raw){
        String s=__SolidCadCanvasView_normalizeDigits(raw==null?"":raw).trim().toLowerCase(Locale.US).replace(" ","");
        if(s.endsWith("mm"))return Float.parseFloat(s.substring(0,s.length()-2));
        if(s.endsWith("cm"))return Float.parseFloat(s.substring(0,s.length()-2))*10f;
        return Float.parseFloat(s);
    }

