    public String undoLastFeature() {
        if(history.isEmpty())return"History is empty";
        Feature f=history.remove(history.size()-1);
        redoHistory.addLast(f);
        producerByBody.remove(f.outputBody);
        List<Object> bs=__ParametricHistorySolidCadCanvasView_bodies();
        bs.remove(f.outputBody);
        if(f instanceof BooleanFeature){
            BooleanFeature b=(BooleanFeature)f;
            if(!bs.contains(b.leftBody))bs.add(b.leftBody);
            if(!bs.contains(b.rightBody))bs.add(b.rightBody);
            __ParametricHistorySolidCadCanvasView_setSelectedBody(b.leftBody);
        }else __ParametricHistorySolidCadCanvasView_setSelectedBody(bs.isEmpty()?null:bs.get(bs.size()-1));
        __ParametricHistorySolidCadCanvasView_setSelectedFace(null);
        invalidate();
        return "Feature text text: "+f.kind;
    }

    public String redoLastFeature(){
        if(redoHistory.isEmpty())return "Redo is empty";
        Feature f=redoHistory.removeLast();
        List<Object> bs=__ParametricHistorySolidCadCanvasView_bodies();
        if(f instanceof BooleanFeature){
            BooleanFeature b=(BooleanFeature)f;
            if(!b.keepLeft)bs.remove(b.leftBody);
            if(!b.keepRight)bs.remove(b.rightBody);
        }
        if(!bs.contains(f.outputBody))bs.add(f.outputBody);
        history.add(f);producerByBody.put(f.outputBody,f);
        __ParametricHistorySolidCadCanvasView_setSelectedBody(f.outputBody);__ParametricHistorySolidCadCanvasView_setSelectedFace(null);
        String rebuilt=rebuildHistory();post(this::fitAll);invalidate();
        return "Feature text text text: "+f.kind+" • "+rebuilt;
    }

