        boolean[] used=new boolean[lines.size()];
        PointF a=__ParametricHistorySolidCadCanvasView_endpoint(lines.get(0),0),b=__ParametricHistorySolidCadCanvasView_endpoint(lines.get(0),1);if(a==null||b==null)return null;
