    public String rebuildHistory(){
        if(rebuildingForms)return super.rebuildHistory();
        rebuildingForms=true;int ok=0,broken=0;
        try{
            for(FormFeature f:formHistory){
                if(!__AdvancedParametricSolidCadCanvasView_sourcesStillExist(f.sourceEntities)){f.broken=true;f.warning="Sketch/text text Delete text";broken++;continue;}
                SolidCSG c=f.build(this);
                if(c==null||c.isEmpty()){f.broken=true;f.warning="Geometry Feature invalid text";broken++;continue;}
                __AdvancedParametricSolidCadCanvasView_setBodyCsg(f.outputBody,c);f.broken=false;f.warning="";ok++;
            }
        }finally{rebuildingForms=false;}
        String base=super.rebuildHistory();
        return base+" • Form "+ok+(broken>0?" • "+broken+" Form Error":"");
    }


