    public void showDirectManager() {
        Object body = __DirectModelCadCanvasView_selectedBody();
        Object face = __DirectModelCadCanvasView_selectedFace();
        String bodyText = body == null ? "No body selected" : __DirectModelCadCanvasView_bodyName(body);
        String faceText = face == null ? "No face selected" : "Face Ready Push/Pull text";
        String edgeText = selectedEdgeA == null ? "No edge selected" : "Edge selected";

        String[] items = {
                "⌁ Selection Edge text touch Roy Model",
                "⌒ Fillet text Edge selected",
                "◩ Chamfer text Edge selected",
                "↕ Push/Pull text Offset Roy Face selected",
                "⌒ Fillet All Edgetext Vertical",
                "◩ Chamfer All Edgetext Vertical",
                "▱ Shell / text",
                "⏱ Direct Edit History",
                "↺ text Direct Edittext Body"
        };

        new AlertDialog.Builder(getContext())
                .setTitle("Edit 3D • text")
                .setMessage(bodyText + "\n" + faceText + " • " + edgeText
                        + " \n  \n text Face text Roy Face text. text Edge text First Hit and then yourself Edge text touch text."
                        + " \n text All Dimensiontext: mm (mm)")
                .setItems(items, (d,w) -> {
                    if (w == 0) __DirectModelCadCanvasView_beginEdgePick();
                    else if (w == 1) __DirectModelCadCanvasView_askEdgeEdit(EditKind.EDGE_FILLET);
                    else if (w == 2) __DirectModelCadCanvasView_askEdgeEdit(EditKind.EDGE_CHAMFER);
                    else if (w == 3) __DirectModelCadCanvasView_askFaceOffset();
                    else if (w == 4) __DirectModelCadCanvasView_askBodyEdit(EditKind.ALL_FILLET);
                    else if (w == 5) __DirectModelCadCanvasView_askBodyEdit(EditKind.ALL_CHAMFER);
                    else if (w == 6) __DirectModelCadCanvasView_askBodyEdit(EditKind.SHELL);
                    else if (w == 7) showDirectHistory();
                    else __DirectModelCadCanvasView_toast(__DirectModelCadCanvasView_clearDirectEdits());
                })
                .setNegativeButton("Close", null)
                .show();
    }

    /** Keep the old Finish entry useful: it now opens the more capable adaptive editor. */
