    private void restoreDirectBase(Object body) {
        SolidCSG base = directBaseByBody.get(body);
        if (base != null) __DirectModelCadCanvasView_setBodyCsg(body, base.copy());
    }

    private String rebuildDirect(Object body) {
        SolidCSG base = directBaseByBody.get(body);
        if (base == null) return "Error: Direct Edit base was not found";
        List<DirectOp> ops = directOpsByBody.get(body);
        if (ops == null || ops.isEmpty()) { __DirectModelCadCanvasView_setBodyCsg(body, base.copy()); return "Direct Edit is empty"; }
        SolidCSG result = base.copy();
        for (DirectOp op : ops) {
            PrismData p = __DirectModelCadCanvasView_analyzePrism(result);
            if (p == null) return "Error: text Direct Edit text text Body Prism/Extrude text text";
            if (op.kind == EditKind.EDGE_FILLET) {
                int corner = __DirectModelCadCanvasView_nearestCorner(p, op.anchor);
                List<PointF> q = __DirectModelCadCanvasView_filletOne(p.profile, corner, op.valueMm);
                if (q == null) return "Error: Radius Fillet for Edge Selection is large or invalid";
                result = SolidCSG.extrude(q, p.plane, p.heightMm);
            } else if (op.kind == EditKind.EDGE_CHAMFER) {
                int corner = __DirectModelCadCanvasView_nearestCorner(p, op.anchor);
                List<PointF> q = __DirectModelCadCanvasView_chamferOne(p.profile, corner, op.valueMm);
                if (q == null) return "Error: Chamfer text Edge Selectiontext text text invalid text";
                result = SolidCSG.extrude(q, p.plane, p.heightMm);
            } else if (op.kind == EditKind.FACE_OFFSET) {
                result = __DirectModelCadCanvasView_offsetFace(p, op);
                if (result == null || result.isEmpty()) return "Error: text Face invalid text";
            } else if (op.kind == EditKind.ALL_FILLET) {
                List<PointF> q = __DirectModelCadCanvasView_filletAll(p.profile, op.valueMm);
                if (q == null) return "Error: Radius Fillet text text Body text text";
                result = SolidCSG.extrude(q, p.plane, p.heightMm);
            } else if (op.kind == EditKind.ALL_CHAMFER) {
                List<PointF> q = __DirectModelCadCanvasView_chamferAll(p.profile, op.valueMm);
                if (q == null) return "Error: Chamfer text text Body text text";
                result = SolidCSG.extrude(q, p.plane, p.heightMm);
            } else {
                if (op.valueMm >= p.heightMm * 0.49f) return "Error: Thickness Shell text Height Body text text";
                List<PointF> inner = __DirectModelCadCanvasView_insetProfile(p.profile, op.valueMm);
                if (inner == null) return "Error: Thickness Shell text text text text text";
                Geometry3D.Plane3D innerPlane = p.plane.offset(op.valueMm, "Shell inner");
                SolidCSG cut = SolidCSG.extrude(inner, innerPlane, p.heightMm + op.valueMm * 1.5f);
                result = result.subtract(cut);
                if (result.isEmpty()) return "Error: Shell invalid text";
            }
        }
        __DirectModelCadCanvasView_setBodyCsg(body, result);
        invalidate();
        return "Direct Edit Rebuild text • " + ops.size() + " Feature";
    }

    /**
     * When upstream Sketch/Extrude/Form history changes, the parent rebuilds the
     * source body first. If the result changed, capture it as the new direct-edit
     * base and replay the direct feature stack.
     */

    public String rebuildHistory() {
        IdentityHashMap<Object,String> before = new IdentityHashMap<>();
        for (Object body : directOpsByBody.keySet()) before.put(body, __DirectModelCadCanvasView_csgSignature(__DirectModelCadCanvasView_bodyCsg(body)));
        String parent = __ParametricHistorySolidCadCanvasView_rebuildHistory();
        int replayed = 0;
        for (Object body : new ArrayList<>(directOpsByBody.keySet())) {
            SolidCSG after = __DirectModelCadCanvasView_bodyCsg(body);
            if (after == null) continue;
            String old = before.get(body), now = __DirectModelCadCanvasView_csgSignature(after);
            if (old == null || !old.equals(now)) directBaseByBody.put(body, after.copy());
            String r = __DirectModelCadCanvasView_rebuildDirect(body);
            if (!r.startsWith("Error")) replayed++;
        }
        return parent + (replayed > 0 ? " • Direct " + replayed : "");
    }

