    private List<ExactEdgeRecord> exactEdges(Object output){
        BooleanFeatureRef f=__ExactBooleanCadCanvasView_findBooleanFeature(output);
        if(f==null)return Collections.emptyList();
        List<ExactEdgeRecord> out=new ArrayList<>();
        Map<String,ExactEdgeRecord> unique=new LinkedHashMap<>();

        AnalyticSolidKernel.Primitive lp=__ExactBooleanCadCanvasView_primitive(f.left),rp=__ExactBooleanCadCanvasView_primitive(f.right);
        if(lp!=null&&rp!=null){
            ExactIntersectionKernel.PlaneSection pair=ExactIntersectionKernel.intersectPrimitivePair(lp,rp);
            if(pair!=null)__ExactBooleanCadCanvasView_add(unique,new ExactEdgeRecord("CURVED↔CURVED",__ExactBooleanCadCanvasView_bodyName(f.left)+" × "+__ExactBooleanCadCanvasView_bodyName(f.right),pair));
        }

        // For Subtract, the right body is the cutter. Its exact surface meeting
        // host planar faces produces the semantic hole/opening loops.
        if("SUBTRACT".equals(f.operation)){
            if(rp!=null && lp==null)__ExactBooleanCadCanvasView_addPlanarIntersections(unique,"CUT EDGE",__ExactBooleanCadCanvasView_bodyName(f.right),rp,__ExactBooleanCadCanvasView_bodyCsg(f.left));
            // Nested hosts can contain both planar and analytic boundaries. We
            // still extract trustworthy plane intersections from their current B-Rep.
            if(rp!=null && lp==null && __ExactBooleanCadCanvasView_findBooleanFeature(f.left)!=null){
                __ExactBooleanCadCanvasView_addPlanarIntersections(unique,"CUT EDGE",__ExactBooleanCadCanvasView_bodyName(f.right),rp,__ExactBooleanCadCanvasView_bodyCsg(f.left));
            }
        }else{
            if(rp!=null&&lp==null)__ExactBooleanCadCanvasView_addPlanarIntersections(unique,"RIGHT TRIM",__ExactBooleanCadCanvasView_bodyName(f.right),rp,__ExactBooleanCadCanvasView_bodyCsg(f.left));
            if(lp!=null&&rp==null)__ExactBooleanCadCanvasView_addPlanarIntersections(unique,"LEFT TRIM",__ExactBooleanCadCanvasView_bodyName(f.left),lp,__ExactBooleanCadCanvasView_bodyCsg(f.right));
        }

        out.addAll(unique.values());
        return out;
    }

    private void addPlanarIntersections(Map<String,ExactEdgeRecord> out,String role,String source,
                                        AnalyticSolidKernel.Primitive primitive,SolidCSG host){
        for(ExactIntersectionKernel.BoundaryCurve c:ExactIntersectionKernel.intersectWithPlanarBody(primitive,host)){
            ExactEdgeRecord r=new ExactEdgeRecord(role,source,c.section);
            __ExactBooleanCadCanvasView_add(out,r);
        }
    }

    private static void add(Map<String,ExactEdgeRecord> out,ExactEdgeRecord r){
        ExactIntersectionKernel.PlaneSection s=r.section;
        String key=s.type+"|"+(s.center==null?"":__ExactBooleanCadCanvasView_q(s.center.x)+","+__ExactBooleanCadCanvasView_q(s.center.y)+","+__ExactBooleanCadCanvasView_q(s.center.z))+"|"+__ExactBooleanCadCanvasView_q(s.radiusA)+","+__ExactBooleanCadCanvasView_q(s.radiusB)+"|"+__ExactBooleanCadCanvasView_q(s.planeNormal.x)+","+__ExactBooleanCadCanvasView_q(s.planeNormal.y)+","+__ExactBooleanCadCanvasView_q(s.planeNormal.z);
        if(!out.containsKey(key))out.put(key,r);
    }

    private AnalyticSolidKernel.Primitive primitive(Object body){
        SolidCSG c=__ExactBooleanCadCanvasView_bodyCsg(body);return c==null?null:AnalyticSolidKernel.recognize(c);
    }

    private BooleanFeatureRef findBooleanFeature(Object output){
        if(output==null)return null;
        for(Object f:__ExactBooleanCadCanvasView_history()){
            if(f==null||!"BooleanFeature".equals(f.getClass().getSimpleName()))continue;
            try{
                Field of=__ExactBooleanCadCanvasView_findField(f.getClass(),"outputBody");if(of==null||of.get(f)!=output)continue;
                Field op=__ExactBooleanCadCanvasView_findField(f.getClass(),"operation"),lf=__ExactBooleanCadCanvasView_findField(f.getClass(),"leftBody"),rf=__ExactBooleanCadCanvasView_findField(f.getClass(),"rightBody");
                if(op==null||lf==null||rf==null)return null;
                return new BooleanFeatureRef(String.valueOf(op.get(f)),lf.get(f),rf.get(f),output);
            }catch(Exception ignored){}
        }
        return null;
    }

