    private String historySignature(List<Object> base,List<Object> forms){
        StringBuilder s=new StringBuilder();
        s.append("B").append(base.size()).append('|');
        for(Object f:base){
            if(f==null)continue;
            String type=f.getClass().getSimpleName();
            Object out=__OcctModelCadCanvasView_value(f,"outputBody");
            s.append(type).append(':').append(System.identityHashCode(out)).append(':');
            if("ExtrudeFeature".equals(type)){
                s.append(__OcctModelCadCanvasView_number(f,"heightMm")).append(':').append(String.valueOf(__OcctModelCadCanvasView_value(f,"signature")));
            }else if("BooleanFeature".equals(type)){
                s.append(String.valueOf(__OcctModelCadCanvasView_value(f,"operation"))).append(':')
                        .append(System.identityHashCode(__OcctModelCadCanvasView_value(f,"leftBody"))).append(':')
                        .append(System.identityHashCode(__OcctModelCadCanvasView_value(f,"rightBody")));
            }
            s.append(':').append(__OcctModelCadCanvasView_bodyGeometrySignature(out)).append(':').append(__OcctModelCadCanvasView_hasDirectEdits(out)).append('|');
        }
        s.append("F").append(forms.size()).append('|');
        for(Object f:forms){
            if(f==null)continue;
            Object out=__OcctModelCadCanvasView_value(f,"outputBody");
            s.append(f.getClass().getSimpleName()).append(':').append(System.identityHashCode(out)).append(':');
            if("RevolveFeature".equals(f.getClass().getSimpleName()))s.append(__OcctModelCadCanvasView_number(f,"angleDeg")).append(':').append(__OcctModelCadCanvasView_number(f,"heightMm"));
            s.append(':').append(__OcctModelCadCanvasView_bodyGeometrySignature(out)).append(':').append(__OcctModelCadCanvasView_hasDirectEdits(out)).append('|');
        }
        return s.toString();
    }

    private String bodyGeometrySignature(Object body){
        SolidCSG c=__OcctModelCadCanvasView_bodyCsg(body);
        if(c==null)return"0";
        long count=0;
        double sx=0,sy=0,sz=0,sq=0;
        for(SolidCSG.Polygon p:c.polygons())for(SolidCSG.Vertex v:p.vertices){
            count++;sx+=v.pos.x;sy+=v.pos.y;sz+=v.pos.z;
            sq+=v.pos.x*v.pos.x+v.pos.y*v.pos.y+v.pos.z*v.pos.z;
        }
        return c.polygons().size()+":"+count+":"+Math.round(sx*100)+":"+Math.round(sy*100)+":"+Math.round(sz*100)+":"+Math.round(sq*10);
    }

    private SolidCSG bodyCsg(Object body){
        Object c=__OcctModelCadCanvasView_value(body,"csg");return c instanceof SolidCSG?(SolidCSG)c:null;
    }

