        Geometry3D.Vec3 turned=__OcctStableCadCanvasView_rotatePoint(alignSourcePoint,center,axis,Math.toRadians(angle));
        alignRotationAxis=axis;alignRotationDeg=angle;alignMove=alignTargetPoint.sub(turned);
        Object record=__OcctStableCadCanvasView_ensureNativeRecord(alignBody);if(record==null)return false;__OcctStableCadCanvasView_clearFeaturePreview();long current=__OcctStableCadCanvasView_recordHandle(record);List<Long> temp=new ArrayList<>();
