     public String applySymmetryConstraint() {
        if (!prepareTransactionalSelection("constraint-symmetry-prepare")) {
            return "Symmetry requires source, mirror and axis lines";
        }
        List<String> ids = selectedModelLineIds();
        if (ids.size() != 3 || sketchDocument.selectionIds().size() != 3) {
            return "Symmetry requires source, mirror and axis lines";
        }
        String sourceId = ids.get(0);
        String mirrorId = ids.get(1);
        String axisId = ids.get(2);
        for (SketchConstraint existing : sketchDocument.constraints()) {
            if (existing.kind != SketchConstraint.Kind.SYMMETRY) continue;
            if (sourceId.equals(existing.primaryEntityId)
                    && mirrorId.equals(existing.secondaryEntityId)
                    && axisId.equals(existing.tertiaryEntityId)) {
                return "Symmetry already applied";
            }
        }
        try {
            SketchConstraint symmetry = SketchConstraint.symmetry(
                    UUID.randomUUID().toString(), sourceId, mirrorId, axisId);
            sketchDocument.addConstraintsAndSolve(
                    java.util.Collections.singletonList(symmetry), sketchConstraintSolver);
            coreSaveUndo();
            replaySolvedLineGeometryToLegacy();
            if (!finishTransactionalMutation("constraint-symmetry")) {
                return "Symmetry constraint rollback: parity failed";
            }
            invalidate();
            return "Symmetry applied";
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-symmetry", e);
        }
    }

     public String applyMidpointConstraint() {
        if (!prepareTransactionalSelection("constraint-midpoint-prepare")) {
            return "Midpoint requires exactly two lines";
        }
        List<String> ids = selectedModelLineIds();
        if (ids.size() != 2) return "Midpoint requires exactly two lines";
        String drivenId = ids.get(0);
        String hostId = ids.get(1);
        if (drivenId.equals(hostId)) return "Midpoint requires two distinct lines";
        SketchGeometry.Line driven = (SketchGeometry.Line) sketchDocument.entity(drivenId);
        SketchGeometry.Line host = (SketchGeometry.Line) sketchDocument.entity(hostId);
        double midpointX = (host.a.xMm + host.b.xMm) * 0.5d;
        double midpointY = (host.a.yMm + host.b.yMm) * 0.5d;
        double d0 = Math.hypot(driven.a.xMm - midpointX, driven.a.yMm - midpointY);
        double d1 = Math.hypot(driven.b.xMm - midpointX, driven.b.yMm - midpointY);
        int drivenPoint = d0 <= d1 ? 0 : 1;
        try {
            SketchConstraint midpoint = SketchConstraint.midpoint(
                    UUID.randomUUID().toString(), drivenId, drivenPoint, hostId);
            sketchDocument.addConstraintsAndSolve(
                    java.util.Collections.singletonList(midpoint), sketchConstraintSolver);
            coreSaveUndo();
            replaySolvedLineGeometryToLegacy();
            if (!finishTransactionalMutation("constraint-midpoint")) {
                return "Midpoint constraint rollback: parity failed";
            }
            return "Midpoint applied";
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-midpoint", e);
        }
    }

     public String applyTangentConstraint() {
        if (!prepareTransactionalSelection("constraint-tangent-prepare")) {
            return "Tangent requires exactly one line and one circle/arc";
        }
        Set<String> selectedIds = sketchDocument.selectionIds();
        if (selectedIds.size() != 2) return "Tangent requires exactly one line and one circle/arc";
        String lineId = null;
        String curveId = null;
        for (String id : selectedIds) {
            SketchEntity entity = sketchDocument.entity(id);
            if (entity instanceof SketchGeometry.Line) {
                if (lineId != null) return "Tangent requires exactly one line and one circle/arc";
                lineId = id;
            } else if (entity instanceof SketchGeometry.Circle || entity instanceof SketchGeometry.Arc) {
                if (curveId != null) return "Tangent requires exactly one line and one circle/arc";
                curveId = id;
            } else {
                return "Tangent requires exactly one line and one circle/arc";
            }
        }
        if (lineId == null || curveId == null) return "Tangent requires exactly one line and one circle/arc";
        for (SketchConstraint existing : sketchDocument.constraints()) {
            if (existing.kind != SketchConstraint.Kind.TANGENT || existing.secondaryEntityId == null) continue;
            boolean same = lineId.equals(existing.primaryEntityId) && curveId.equals(existing.secondaryEntityId);
            boolean reverse = curveId.equals(existing.primaryEntityId) && lineId.equals(existing.secondaryEntityId);
            if (same || reverse) return "Tangent already applied";
        }
        try {
            SketchConstraint tangent = SketchConstraint.tangent(UUID.randomUUID().toString(), lineId, curveId);
            sketchDocument.addConstraintsAndSolve(
                    java.util.Collections.singletonList(tangent), sketchConstraintSolver);
            coreSaveUndo();
            replaySolvedLineGeometryToLegacy();
            if (!finishTransactionalMutation("constraint-tangent")) {
                return "Tangent constraint rollback: parity failed";
            }
            invalidate();
            return "Tangent applied";
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-tangent", e);
        }
    }

     public String applyConcentricConstraint() {
        if (!prepareTransactionalSelection("constraint-concentric-prepare")) {
            return "Concentric requires exactly two circles/arcs";
        }
        List<String> ids = selectedModelCurveIds();
        if (ids.size() != 2 || sketchDocument.selectionIds().size() != 2) {
            return "Concentric requires exactly two circles/arcs";
        }
        // Preserve the established Concentric interaction contract: the first
        // selected curve is the anchor and the second is driven. FIXED on the
        // driven center must therefore conflict atomically instead of silently
        // reversing authority.
        String anchorId = ids.get(0);
        String drivenId = ids.get(1);
        for (SketchConstraint existing : sketchDocument.constraints()) {
            if (existing.kind != SketchConstraint.Kind.CONCENTRIC
                    || existing.secondaryEntityId == null) continue;
            boolean same = anchorId.equals(existing.primaryEntityId)
                    && drivenId.equals(existing.secondaryEntityId);
            boolean reverse = drivenId.equals(existing.primaryEntityId)
                    && anchorId.equals(existing.secondaryEntityId);
            if (same || reverse) return "Concentric already applied";
        }
        try {
            SketchConstraint concentric = SketchConstraint.concentric(
                    UUID.randomUUID().toString(), anchorId, drivenId);
            sketchDocument.addConstraintsAndSolve(
                    java.util.Collections.singletonList(concentric), sketchConstraintSolver);
            coreSaveUndo();
            replaySolvedLineGeometryToLegacy();
            if (!finishTransactionalMutation("constraint-concentric")) {
                return "Concentric constraint rollback: parity failed";
            }
            invalidate();
            return "Concentric applied";
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-concentric", e);
        }
    }

    private static boolean isDisconnectableModelConstraint(SketchConstraint constraint) {
        return constraint != null && (constraint.kind == SketchConstraint.Kind.COINCIDENT
                || constraint.kind == SketchConstraint.Kind.POINT_ON_ENTITY
                || constraint.kind == SketchConstraint.Kind.MIDPOINT);
    }

     public String disconnectSelectedConnections() {
        if (!prepareTransactionalSelection("constraint-disconnect-prepare")) return "Select geometry first";
        Set<String> selectedIds = sketchDocument.selectionIds();
        if (selectedIds.isEmpty()) return "Select geometry first";

        ArrayList<String> removeIds = new ArrayList<>();
        for (SketchConstraint constraint : sketchDocument.constraints()) {
            if (!isDisconnectableModelConstraint(constraint)) continue;
            for (String selectedId : selectedIds) {
                if (constraint.references(selectedId)) {
                    removeIds.add(constraint.id);
                    break;
                }
            }
        }
        if (removeIds.isEmpty()) return "No connections to disconnect";

        try {
            int removed = sketchDocument.removeConstraints(removeIds);
            if (removed <= 0) return "No connections to disconnect";
            if (removed != removeIds.size()) {
                if (sketchDocument.canUndo()) sketchDocument.undo();
                return "Disconnect rollback: incomplete model mutation";
            }
            coreSaveUndo();
            if (!finishTransactionalMutation("constraint-disconnect")) {
                return "Disconnect rollback: parity failed";
            }
            invalidate();
            return removed + " connection(s) disconnected";
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-disconnect", e);
        }
    }

    private boolean hasWholeFixed(String entityId) {
        for (SketchConstraint c : sketchDocument.constraintsForEntity(entityId)) {
            if (c.kind == SketchConstraint.Kind.FIXED
                    && entityId.equals(c.primaryEntityId) && c.fixesWholeEntity()) return true;
        }
        return false;
    }

    private String toggleActivePointLock() {
        if (!activePointLockTargetMatchesSelection()) return "Select an endpoint or center point first";
        String entityId = pointLockTargetEntityId;
        int pointIndex = pointLockTargetPointIndex;
        if (!prepareTransactionalSelection("constraint-fixed-point-prepare")) {
            clearPointLockTarget();
            return "Select an endpoint or center point first";
        }
        if (!sketchDocument.selectionIds().contains(entityId)
                || modelPoint(sketchDocument.entity(entityId), pointIndex) == null) {
            clearPointLockTarget();
            return "Point selection is no longer valid";
        }
        boolean shouldLock = !hasPointFixed(entityId, pointIndex);
        try {
            if (shouldLock) {
                SketchConstraint fixed = SketchConstraint.fixedPoint(
                        UUID.randomUUID().toString(), entityId, pointIndex);
                sketchDocument.addConstraintsAndSolve(
                        java.util.Collections.singletonList(fixed), sketchConstraintSolver);
            } else {
                ArrayList<String> removeIds = new ArrayList<>();
                for (SketchConstraint c : sketchDocument.constraintsForEntity(entityId)) {
                    if (c.kind == SketchConstraint.Kind.FIXED && c.fixesPoint()
                            && entityId.equals(c.primaryEntityId)
                            && c.primaryPointIndex == pointIndex) removeIds.add(c.id);
                }
                if (!removeIds.isEmpty()) sketchDocument.removeConstraints(removeIds);
            }
            coreSaveUndo();
            if (!finishTransactionalMutation("constraint-fixed-point")) {
                return "Point Lock rollback: parity failed";
            }
            invalidate();
            return (shouldLock ? "Point locked" : "Point unlocked");
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-fixed-point", e);
        }
    }

     public String toggleSelectedLock() {
        if (activePointLockTargetMatchesSelection()) return toggleActivePointLock();
        if (!prepareTransactionalSelection("constraint-fixed-prepare")) return "Select geometry first";
        Set<String> ids = sketchDocument.selectionIds();
        if (ids.isEmpty()) return "Select geometry first";

        boolean shouldLock = false;
        for (String id : ids) {
            if (!hasWholeFixed(id)) { shouldLock = true; break; }
        }

        try {
            if (shouldLock) {
                ArrayList<SketchConstraint> incoming = new ArrayList<>();
                for (String id : ids) {
                    if (!hasWholeFixed(id)) incoming.add(SketchConstraint.fixed(UUID.randomUUID().toString(), id));
                }
                if (incoming.isEmpty()) return ids.size() + " selection(s) locked";
                sketchDocument.addConstraintsAndSolve(incoming, sketchConstraintSolver);
            } else {
                ArrayList<String> removeIds = new ArrayList<>();
                for (SketchConstraint c : sketchDocument.constraints()) {
                    if (c.kind == SketchConstraint.Kind.FIXED && c.fixesWholeEntity()
                            && ids.contains(c.primaryEntityId)) removeIds.add(c.id);
                }
                if (removeIds.isEmpty()) return ids.size() + " selection(s) unlocked";
                sketchDocument.removeConstraints(removeIds);
            }
            coreSaveUndo();
            if (!finishTransactionalMutation("constraint-fixed")) return "Lock constraint rollback: parity failed";
            invalidate();
            return ids.size() + (shouldLock ? " selection(s) locked" : " selection(s) unlocked");
        } catch (RuntimeException e) {
            return modelConstraintFailure("constraint-fixed", e);
        }
    }

     public String exportSketchProjectState() {
        try {
            JSONObject root=new JSONObject(super.exportSketchProjectState());
            JSONArray rows=new JSONArray();
            for (SketchConstraint c:sketchDocument.constraints()) {
                JSONObject row=new JSONObject();
                row.put("id",c.id);
                row.put("kind",c.kind.name());
                row.put("primaryEntityId",c.primaryEntityId);
                row.put("primaryPointIndex",c.primaryPointIndex);
                if (c.secondaryEntityId!=null) row.put("secondaryEntityId",c.secondaryEntityId);
                row.put("secondaryPointIndex",c.secondaryPointIndex);
                if (c.tertiaryEntityId!=null) row.put("tertiaryEntityId",c.tertiaryEntityId);
                if (!Double.isNaN(c.value)) row.put("value",c.value);
                row.put("driving",c.driving);
                rows.put(row);
            }
            root.put("modelConstraintSchemaVersion",1);
            root.put("modelConstraints",rows);
            return root.toString();
        } catch (Exception e) {
            throw new IllegalStateException("Cannot export model-owned sketch constraints",e);
        }
    }

     public String importSketchProjectState(String raw) {
        try {
            JSONObject incoming=new JSONObject(raw);
            int incomingSchema=incoming.optInt("schemaVersion",-1);
            boolean hasModelConstraints=incomingSchema==2 && incoming.has("modelConstraints");
            if (hasModelConstraints) {
                SketchDocument preflight = new SketchDocument();
                LegacySketchStateBridge.restoreDocument(preflight, raw);
            }
            String out=super.importSketchProjectState(raw);
            if (hasModelConstraints) {
                LegacySketchStateBridge.restoreDocument(sketchDocument,raw);
            } else {
                LegacySketchStateBridge.restoreDocument(sketchDocument,super.exportSketchProjectState());
            }
            mirrorSyncCount++;
            authorityHistoryValid=false;
            lastMirrorError="";
            requireSketchMirrorParity();
            return out;
        } catch (Exception e) {
            authorityHistoryValid=false;
            lastMirrorError="project-open: "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());
            return "Project sketch state could not be restored";
        }
    }

     public String executeCommand(String raw) {
        String newId = UUID.randomUUID().toString();
        SketchEntity planned = exactCreateEntity(raw, newId);
        if (planned != null && prepareTransactionalCreate(planned, "create-command-prepare")) {
            int legacyCountBefore = entities.size();
            String out = super.executeCommand(raw);
            boolean legacyCreated = entities.size() == legacyCountBefore + 1 && selected != null;
            if (!legacyCreated) {
                try { if (sketchDocument.canUndo()) sketchDocument.undo(); } catch (RuntimeException ignored) {}
                syncMirror("create-command-rejected");
                return out;
            }
            boolean injected = restoreLegacySelectedStableId(newId);
            boolean committed = injected && finishTransactionalMutation("create-command");
            if (committed) return out;
            if (!injected) finishTransactionalMutation("create-command-id-injection");
            String fallback = super.executeCommand(raw);
            syncMirror("create-command-fallback");
            return fallback;
        }

        long before = authorityTransitionCount;
        String out = super.executeCommand(raw);
        if (authorityTransitionCount == before) syncMirror("command");
        return out;
    }


